// ============================================================
// Normalize Text v1.0
// 文本标准化层
//
// 职责：
// 1. 保留原始 content_text
// 2. 生成 normalized_text
// 3. 清理格式噪声
// 4. 识别常见拼音 / 英文别名
//
// 不负责：
// - 风险判断
// - P0/P1/P2/P3
// - 情感分类
// - AI 调用
// ============================================================

const items = $input.all();

const NORMALIZATION_VERSION = 'normalize-v1.0';


// ============================================================
// 1. Alias Dictionary（别名字典）
//
// 注意：
// 这里只“检测”这些表达。
// V1 不直接把它们替换成中文，避免代码过度理解语义。
// ============================================================

const ALIAS_PATTERNS = [
  {
    type: 'PINYIN_ALIAS',
    canonical: '恶心',
    regex: /\be\s*xin\b/gi,
  },
  {
    type: 'PINYIN_ALIAS',
    canonical: '头晕',
    regex: /\btou\s*yun\b/gi,
  },
  {
    type: 'PINYIN_ALIAS',
    canonical: '过敏',
    regex: /\bguo\s*min\b/gi,
  },
  {
    type: 'PINYIN_ALIAS',
    canonical: '拉肚子',
    regex: /\bla\s*du\s*zi\b/gi,
  },
  {
    type: 'PINYIN_ALIAS',
    canonical: '假货',
    regex: /\bjia\s*huo\b/gi,
  },

  // 当前测试数据中存在：
  // “seal 好像已经开过了”
  {
    type: 'ENGLISH_ALIAS',
    canonical: '密封',
    regex: /\bseal\b/gi,
  },
];


// ============================================================
// 2. Targeted Traditional Map
//    （高价值繁体字定向映射）
//
// 我们没有在 Code Node 中安装完整繁简转换库。
// 所以这里只处理 VOC 风险领域常见、语义明确的少量词。
//
// 这不是完整繁简转换器。
// ============================================================

const TRADITIONAL_MAP = {
  '過敏': '过敏',
  '頭暈': '头晕',
  '噁心': '恶心',
  '腹瀉': '腹泻',
  '發霉': '发霉',
  '異物': '异物',
  '變質': '变质',
  '服務': '服务',
  '物流': '物流',
};


// ============================================================
// 3. 工具函数
// ============================================================

function cleanOriginal(value) {

  if (value === undefined || value === null) {
    return null;
  }

  const text = String(value);

  if (text.trim() === '') {
    return null;
  }

  return text;
}


function addFlag(flags, flag) {

  if (!flags.includes(flag)) {
    flags.push(flag);
  }

}


function applyTraditionalMap(text, flags) {

  let result = text;

  for (const [traditional, simplified] of Object.entries(TRADITIONAL_MAP)) {

    if (result.includes(traditional)) {
      result = result.split(traditional).join(simplified);

      addFlag(
        flags,
        'TARGETED_TRADITIONAL_NORMALIZED'
      );
    }
  }

  return result;
}


// ============================================================
// 4. Structural Normalization
//    （结构标准化）
//
// 只清理格式，不做风险判断。
// ============================================================

function normalizeStructure(originalText) {

  if (originalText === null) {
    return {
      normalizedText: null,
      flags: ['EMPTY_TEXT'],
    };
  }

  let text = originalText;
  const flags = [];


  // ----------------------------------------------------------
  // 4.1 Unicode NFKC
  //
  // NFKC：
  // Unicode Compatibility Normalization
  // （Unicode兼容标准化）
  //
  // 主要可以把：
  // 全角英文 / 数字等
  // 转成更统一的形式。
  //
  // 例如：
  // ＡＢＣ → ABC
  // １２３ → 123
  // ----------------------------------------------------------

  let before = text;

  text = text.normalize('NFKC');

  if (text !== before) {
    addFlag(flags, 'UNICODE_NFKC_NORMALIZED');
  }


  // ----------------------------------------------------------
  // 4.2 去除 Zero-width Characters
  //     （零宽字符）
  //
  // 有些复制文本里肉眼看不到，但会影响关键词匹配。
  // ----------------------------------------------------------

  before = text;

  text = text.replace(
    /[\u200B-\u200D\uFEFF]/g,
    ''
  );

  if (text !== before) {
    addFlag(flags, 'ZERO_WIDTH_CHAR_REMOVED');
  }


  // ----------------------------------------------------------
  // 4.3 常见 HTML 空格
  //
  // &nbsp;
  // &#160;
  // ----------------------------------------------------------

  before = text;

  text = text.replace(
    /(?:&nbsp;|&#160;)/gi,
    ' '
  );

  if (text !== before) {
    addFlag(flags, 'HTML_SPACE_NORMALIZED');
  }


  // ----------------------------------------------------------
  // 4.4 换行统一为空格
  // ----------------------------------------------------------

  before = text;

  text = text
    .replace(/\r\n?/g, '\n')
    .replace(/\n+/g, ' ');

  if (text !== before) {
    addFlag(flags, 'LINE_BREAK_NORMALIZED');
  }


  // ----------------------------------------------------------
  // 4.5 Tab 等空白统一
  // ----------------------------------------------------------

  before = text;

  text = text.replace(
    /[\t\f\v]+/g,
    ' '
  );

  if (text !== before) {
    addFlag(flags, 'WHITESPACE_NORMALIZED');
  }


  // ----------------------------------------------------------
  // 4.6 多个连续空格 → 一个空格
  // ----------------------------------------------------------

  before = text;

  text = text
    .replace(/\s+/g, ' ')
    .trim();

  if (text !== before) {
    addFlag(flags, 'WHITESPACE_COLLAPSED');
  }


  // ----------------------------------------------------------
  // 4.7 去掉中文字符之间不自然的空格
  //
  // 示例：
  // 吃 完 以后
  // →
  // 吃完以后
  //
  // 但：
  // tou yun
  //
  // 会保留，因为它是拉丁字母。
  // ----------------------------------------------------------

  before = text;

  let previousText;

  do {

    previousText = text;

    text = text.replace(
      /([\u3400-\u9FFF])\s+(?=[\u3400-\u9FFF])/g,
      '$1'
    );

  } while (text !== previousText);

  if (text !== before) {
    addFlag(flags, 'CJK_SPACE_REMOVED');
  }


  // ----------------------------------------------------------
  // 4.8 清理标点两侧多余空格
  // ----------------------------------------------------------

  before = text;

  text = text.replace(
    /\s*([，。！？；：、,.!?;:])\s*/g,
    '$1'
  );

  if (text !== before) {
    addFlag(flags, 'PUNCTUATION_SPACE_NORMALIZED');
  }


  // ----------------------------------------------------------
  // 4.9 英文字母统一小写
  //
  // ExIn
  // →
  // exin
  //
  // 中文不会受影响。
  // ----------------------------------------------------------

  before = text;

  text = text.toLowerCase();

  if (text !== before) {
    addFlag(flags, 'LATIN_LOWERCASED');
  }


  // ----------------------------------------------------------
  // 4.10 重复标点压缩
  //
  // ！！！ → ！
  // ???   → ?
  // 。。。 → 。
  //
  // 注意：
  // 原始 content_text 仍然保留，
  // 所以不会丢失原始表达。
  // ----------------------------------------------------------

  before = text;

  text = text
    .replace(/！{2,}/g, '！')
    .replace(/!{2,}/g, '!')
    .replace(/？{2,}/g, '？')
    .replace(/\?{2,}/g, '?')
    .replace(/。{2,}/g, '。')
    .replace(/，{2,}/g, '，')
    .replace(/,{2,}/g, ',');

  if (text !== before) {
    addFlag(
      flags,
      'REPEATED_PUNCTUATION_COLLAPSED'
    );
  }


  // ----------------------------------------------------------
  // 4.11 高价值繁体词定向转换
  // ----------------------------------------------------------

  text = applyTraditionalMap(
    text,
    flags
  );


  return {
    normalizedText: text,
    flags,
  };
}


// ============================================================
// 5. Alias Detection
//    （别名检测）
//
// 例如：
// tou yun
// exin
// guomin
// seal
//
// 这里只告诉后面的 Rule Engine：
// “我发现了这个可能的表达。”
//
// 不直接判风险。
// ============================================================

function detectAliases(text) {

  if (!text) {
    return [];
  }

  const detected = [];

  for (const alias of ALIAS_PATTERNS) {

    const matches = text.match(alias.regex);

    if (!matches || matches.length === 0) {
      continue;
    }

    detected.push({
      type: alias.type,

      matched: [
        ...new Set(matches)
      ],

      canonical: alias.canonical,
    });
  }

  return detected;
}


// ============================================================
// 6. 主处理逻辑
// ============================================================

const output = [];

for (const item of items) {

  const row = item.json;

  const originalText =
    cleanOriginal(row.content_text);

  const {
    normalizedText,
    flags,
  } = normalizeStructure(originalText);

  const detectedAliases =
    detectAliases(normalizedText);


  // 如果检测到拼音 Alias（别名）
  if (
    detectedAliases.some(
      alias => alias.type === 'PINYIN_ALIAS'
    )
  ) {
    addFlag(
      flags,
      'PINYIN_ALIAS_DETECTED'
    );
  }


  // 如果检测到英文 Alias
  if (
    detectedAliases.some(
      alias => alias.type === 'ENGLISH_ALIAS'
    )
  ) {
    addFlag(
      flags,
      'ENGLISH_ALIAS_DETECTED'
    );
  }


  output.push({
    json: {

      // 保留前面 Mapper 的所有字段
      ...row,

      // 以下字段只是 n8n 工作流内部使用
      normalized_text: normalizedText,

      normalization_version:
        NORMALIZATION_VERSION,

      normalization_changed:
        normalizedText !== originalText,

      normalization_flags:
        flags,

      detected_aliases:
        detectedAliases,
    }
  });
}


return output;

// ============================================================
// Rule Engine v1.0
// rules-supplement-v1.0
//
// 职责：
// 1. 根据 normalized_text 执行确定性业务规则
// 2. 输出 rule_hit / rule_tags / rule_risk_level / need_ai
// 3. 区分 NONE 与 UNKNOWN
// 4. 处理否定语境
// 5. 处理评分与文本冲突
// 6. 支持少量 Thread Context（评价线程上下文）
//
// 当前不负责：
// - 调用 Dify
// - 生成 AI 结果
// - Final Decision
// - 写飞书
// ============================================================

const items = $input.all();

const RULES_VERSION = 'rules-supplement-v1.0';

const RISK_SCORE = {
  P0: 4,
  P1: 3,
  P2: 2,
  P3: 1,
  NONE: 0,
};


// ============================================================
// 1. 基础工具函数
// ============================================================

function pushUnique(array, value) {
  if (!array.includes(value)) {
    array.push(value);
  }
}


function textOf(row) {
  return String(
    row.normalized_text ??
    row.content_text ??
    ''
  ).trim();
}


function isEmpty(value) {
  return (
    value === null ||
    value === undefined ||
    String(value).trim() === ''
  );
}


function numberOrNull(value) {
  if (isEmpty(value)) {
    return null;
  }

  const number = Number(value);

  return Number.isFinite(number)
    ? number
    : null;
}


function getAliasCanonicals(row) {
  if (!Array.isArray(row.detected_aliases)) {
    return [];
  }

  return row.detected_aliases
    .map(item => item?.canonical)
    .filter(Boolean);
}


// ============================================================
// 2. 单条内容规则判断
// ============================================================

function evaluateItem(row) {

  const text = textOf(row);

  // ----------------------------------------------------------
  // SELLER_REPLY（商家回复）
  //
  // RAW 中保留商家回复用于线程和审计，
  // 但它不是消费者 VOC，因此当前 MVP 不进入风险分析。
  // ----------------------------------------------------------

  if (row.content_type === 'SELLER_REPLY') {

    return {
      analysis_scope: 'OUT_OF_SCOPE',
      skip_reason: 'SELLER_REPLY_NOT_CONSUMER_VOC',

      rules_version: RULES_VERSION,

      rule_hit: false,
      rule_tags: [],

      rule_risk_level: null,

      // n8n 内部临时字段
      rule_decision: 'SKIPPED',

      need_ai: false,

      rule_category: null,
      matched_rule_ids: [],
      hard_risk_hit: false,

      rule_reason:
        '商家回复属于商家侧内容，当前 MVP 不进入消费者 VOC 风险分析。',

      _rule_internal: {
        risk_hits: [],
        data_quality_tags: [],
      },
    };
  }


  // ==========================================================
  // 3. 初始化
  // ==========================================================

  const businessTags = [];
  const metaTags = [];
  const dataQualityTags = [];

  const riskHits = [];
  const matchedRuleIds = [];

  let needAi = false;


  function addRiskHit({
    id,
    tag,
    risk,
    category,
    issueKey,
    hardRisk = false,
  }) {

    pushUnique(businessTags, tag);
    pushUnique(matchedRuleIds, id);

    riskHits.push({
      id,
      tag,
      risk,
      category,
      issueKey,
      hardRisk,
    });
  }


  // ==========================================================
  // 4. Data Quality Rules（数据质量规则）
  //
  // 注意：
  // 数据缺失不是消费者风险。
  // 这里只打 Tag（标签），不提高风险等级。
  // ==========================================================

  const isBuyerContent = [
    'INITIAL_REVIEW',
    'FOLLOWUP_REVIEW',
    'BUYER_REPLY',
  ].includes(row.content_type);


  if (isBuyerContent) {

    if (isEmpty(row.sku_id)) {
      pushUnique(
        dataQualityTags,
        'MISSING_SKU'
      );
    }

    if (isEmpty(row.service_rating)) {
      pushUnique(
        dataQualityTags,
        'MISSING_SERVICE_RATING'
      );
    }

    if (isEmpty(row.logistics_rating)) {
      pushUnique(
        dataQualityTags,
        'MISSING_LOGISTICS_RATING'
      );
    }
  }


  // ==========================================================
  // 5. Negation Context（否定语境）
  //
  // 例如：
  // “没有出现漏液”
  // “担心过敏，但没有不舒服”
  //
  // 不能因为出现“漏液”“过敏”就误报。
  // ==========================================================

  const hasNegationContext =
    /没有出现漏液/.test(text) ||
    /本来担心会过敏.*没有不舒服/.test(text) ||
    /没有破损/.test(text) ||
    /密封膜(?:是)?完整/.test(text) ||
    /没有出现恶心或者拉肚子/.test(text) ||
    /没有出现(?:恶心|拉肚子)/.test(text);


  if (hasNegationContext) {
    pushUnique(
      metaTags,
      'NEGATION_CONTEXT'
    );
  }


  // ==========================================================
  // 6. P0 — 产品安全 / 身体不适
  // ==========================================================


  // ----------------------------------------------------------
  // P0：胃部不适
  // ----------------------------------------------------------

  if (
    /胃(?:一直)?不太舒服|胃不舒服|胃疼|胃痛/.test(text)
  ) {

    addRiskHit({
      id: 'R_P0_STOMACH_DISCOMFORT',
      tag: 'STOMACH_DISCOMFORT',
      risk: 'P0',
      category: '产品安全',
      issueKey: 'HEALTH',
      hardRisk: true,
    });
  }


  // ----------------------------------------------------------
  // P0：恶心 / 想吐
  //
  // 要求同时存在消费使用语境，
  // 避免“看到虫子太恶心了”被理解成身体症状。
  // ----------------------------------------------------------

  const hasUseContext =
    /吃了|吃完|服用|喝了|喝完|使用后|吃完以后|吃完当天/.test(text);


  const nauseaNegated =
    /没有出现[^。！？，,]*(?:恶心|想吐)/.test(text) ||
    /没有(?:恶心|想吐)/.test(text);


  const disgustContext =
    /发霉|虫子|虫卵|异物|黑色的东西/.test(text) &&
    /太恶心/.test(text);


  if (
    /恶心|想吐/.test(text) &&
    hasUseContext &&
    !nauseaNegated &&
    !disgustContext
  ) {

    addRiskHit({
      id: 'R_P0_NAUSEA',
      tag: 'NAUSEA',
      risk: 'P0',
      category: '产品安全',
      issueKey: 'HEALTH',
      hardRisk: true,
    });
  }


  // ----------------------------------------------------------
  // P0：头晕
  // ----------------------------------------------------------

  if (
    /头晕|会晕一下|站起来[^。！？，,]*晕/.test(text)
  ) {

    addRiskHit({
      id: 'R_P0_DIZZY',
      tag: 'DIZZY',
      risk: 'P0',
      category: '产品安全',
      issueKey: 'HEALTH',
      hardRisk: true,
    });
  }


  // ----------------------------------------------------------
  // P0：腹泻 / 拉肚子
  // ----------------------------------------------------------

  const diarrheaNegated =
    /没有出现[^。！？，,]*拉肚子/.test(text) ||
    /没有拉肚子/.test(text);


  if (
    /拉肚子|腹泻/.test(text) &&
    hasUseContext &&
    !diarrheaNegated
  ) {

    addRiskHit({
      id: 'R_P0_DIARRHEA',
      tag: 'DIARRHEA',
      risk: 'P0',
      category: '产品安全',
      issueKey: 'HEALTH',
      hardRisk: true,
    });
  }


  // ----------------------------------------------------------
  // P0：红疹 / 疑似过敏表现
  // ----------------------------------------------------------

  if (
    /红疹|起疹|一片一片的很痒/.test(text) &&
    hasUseContext
  ) {

    addRiskHit({
      id: 'R_P0_ALLERGY_RASH',
      tag: 'ALLERGY_RASH',
      risk: 'P0',
      category: '产品安全',
      issueKey: 'HEALTH',
      hardRisk: true,
    });
  }


  // ----------------------------------------------------------
  // P0：发霉 / 异物 / 虫子
  // ----------------------------------------------------------

  if (
    /发霉|虫子|虫卵|异物|黑色的东西/.test(text)
  ) {

    addRiskHit({
      id: 'R_P0_MOLD_FOREIGN_OBJECT',
      tag: 'MOLD_FOREIGN_OBJECT',
      risk: 'P0',
      category: '产品安全',
      issueKey: 'QUALITY_SAFETY',
      hardRisk: true,
    });
  }


  // ==========================================================
  // 7. P1 — 真伪 / 包装完整性 / 严重质量
  // ==========================================================


  // ----------------------------------------------------------
  // 防伪码异常
  // ----------------------------------------------------------

  if (
    /防伪码[^。！？，,]*(?:查不出来|异常)/.test(text) ||
    /扫了[^。！？，,]*显示异常/.test(text)
  ) {

    addRiskHit({
      id: 'R_P1_ANTIFRAUD_CODE',
      tag: 'ANTIFRAUD_CODE_ABNORMAL',
      risk: 'P1',
      category: '真伪/资质',
      issueKey: 'AUTHENTICITY',
      hardRisk: false,
    });
  }


  // ----------------------------------------------------------
  // 强真伪质疑
  // ----------------------------------------------------------

  const strongAuthenticityDoubt =
    /(?:很)?怀疑(?:是不是|不是)?正品/.test(text) ||
    /怀疑不是正品/.test(text) ||
    /假货/.test(text);


  // ----------------------------------------------------------
  // 弱真伪质疑
  //
  // “不知道是不是正品”
  // 不能由代码强行定为 P1。
  // ----------------------------------------------------------

  const weakAuthenticityDoubt =
    /不知道是不是正品/.test(text) &&
    !strongAuthenticityDoubt;


  if (strongAuthenticityDoubt) {

    addRiskHit({
      id: 'R_P1_AUTHENTICITY_DOUBT',
      tag: 'AUTHENTICITY_DOUBT',
      risk: 'P1',
      category: '真伪/资质',
      issueKey: 'AUTHENTICITY',
      hardRisk: false,
    });

    needAi = true;
  }


  if (weakAuthenticityDoubt) {

    pushUnique(
      businessTags,
      'AUTHENTICITY_DOUBT_WEAK'
    );

    pushUnique(
      matchedRuleIds,
      'R_UNKNOWN_AUTHENTICITY_WEAK'
    );

    needAi = true;
  }


  // ----------------------------------------------------------
  // 密封膜缺失 / 松动
  //
  // 注意：
  // “没有密封膜”本身就是风险，
  // 不能被普通否定规则误杀。
  // ----------------------------------------------------------

  if (
    /没有密封膜|无密封膜/.test(text) ||
    /密封膜[^。！？，,]*(?:松|破)/.test(text)
  ) {

    addRiskHit({
      id: 'R_P1_SEAL_MISSING',
      tag: 'SEAL_MISSING',
      risk: 'P1',
      category: '产品质量',
      issueKey: 'PACKAGING_INTEGRITY',
      hardRisk: true,
    });
  }


  // ----------------------------------------------------------
  // 疑似拆封
  // ----------------------------------------------------------

  if (
    /像被拆开过/.test(text) ||
    /开过了/.test(text) ||
    /胶带是重新贴的/.test(text)
  ) {

    addRiskHit({
      id: 'R_P1_PACKAGE_OPENED',
      tag: 'PACKAGE_OPENED',
      risk: 'P1',
      category: '产品质量',
      issueKey: 'PACKAGING_INTEGRITY',
      hardRisk: true,
    });
  }


  // ----------------------------------------------------------
  // 临期
  // ----------------------------------------------------------

  if (
    /临期/.test(text) ||
    /只剩半年不到/.test(text) ||
    /剩半年不到/.test(text)
  ) {

    addRiskHit({
      id: 'R_P1_NEAR_EXPIRY',
      tag: 'NEAR_EXPIRY',
      risk: 'P1',
      category: '产品质量',
      issueKey: 'EXPIRY',
      hardRisk: true,
    });
  }


  // ----------------------------------------------------------
  // 严重漏液
  // ----------------------------------------------------------

  const leakageNegated =
    /没有出现漏液/.test(text) ||
    /没有漏液/.test(text) ||
    /没漏液/.test(text);


  if (
    (
      /漏液/.test(text) ||
      /渗出来/.test(text) ||
      /漏得很严重/.test(text) ||
      /瓶身全是油/.test(text)
    ) &&
    !leakageNegated
  ) {

    addRiskHit({
      id: 'R_P1_LEAKAGE',
      tag: 'LEAKAGE',
      risk: 'P1',
      category: '产品质量',
      issueKey: 'PACKAGING_INTEGRITY',
      hardRisk: true,
    });
  }


  // ==========================================================
  // 8. P2 — 普通明确负面
  // ==========================================================


  // 顺序有意保持：
  // TASTE_BAD → SWEET → SOUR → BITTER
  // 方便测试结果稳定。


  if (/难吃|难喝/.test(text)) {

    addRiskHit({
      id: 'R_P2_TASTE_BAD',
      tag: 'TASTE_BAD',
      risk: 'P2',
      category: '口感体验',
      issueKey: 'TASTE',
    });
  }


  if (
    /太甜/.test(text) ||
    /甜得有点齁/.test(text) ||
    /甜得[^。！？，,]*腻/.test(text)
  ) {

    addRiskHit({
      id: 'R_P2_TASTE_TOO_SWEET',
      tag: 'TASTE_TOO_SWEET',
      risk: 'P2',
      category: '口感体验',
      issueKey: 'TASTE',
    });
  }


  if (/太酸|有点酸/.test(text)) {

    addRiskHit({
      id: 'R_P2_TASTE_TOO_SOUR',
      tag: 'TASTE_TOO_SOUR',
      risk: 'P2',
      category: '口感体验',
      issueKey: 'TASTE',
    });
  }


  if (/有点苦|太苦/.test(text)) {

    addRiskHit({
      id: 'R_P2_TASTE_BITTER',
      tag: 'TASTE_BITTER',
      risk: 'P2',
      category: '口感体验',
      issueKey: 'TASTE',
    });
  }


  // “没啥感觉”
  if (/没啥感觉/.test(text)) {

    addRiskHit({
      id: 'R_P2_NO_EFFECT',
      tag: 'NO_EFFECT',
      risk: 'P2',
      category: '功效预期',
      issueKey: 'EFFECT',
    });
  }


  // “效果一般 / 一点感觉都没有”
  if (
    /效果一般/.test(text) ||
    /一点感觉都没有/.test(text)
  ) {

    addRiskHit({
      id: 'R_P2_EFFECT_WEAK',
      tag: 'EFFECT_WEAK',
      risk: 'P2',
      category: '功效预期',
      issueKey: 'EFFECT',
    });
  }


  if (
    /物流太慢/.test(text) ||
    /物流还慢/.test(text) ||
    /下单一周才到/.test(text) ||
    /等了五天/.test(text)
  ) {

    addRiskHit({
      id: 'R_P2_LOGISTICS_SLOW',
      tag: 'LOGISTICS_SLOW',
      risk: 'P2',
      category: '物流问题',
      issueKey: 'LOGISTICS',
    });
  }


  if (
    /客服回复[^。！？，,]*慢/.test(text) ||
    /问了三天才回/.test(text) ||
    /客服电话[^。！？，,]*没人接/.test(text)
  ) {

    addRiskHit({
      id: 'R_P2_SERVICE_SLOW',
      tag: 'SERVICE_SLOW',
      risk: 'P2',
      category: '客服服务',
      issueKey: 'SERVICE',
    });
  }


  // 真伪怀疑中的“味道异常”
  // 这里将其视为 AUTHENTICITY 的支持证据，
  // 不单独制造 MULTI_ISSUE。
  if (
    /味道和上次买的明显不一样/.test(text) ||
    /甜得发苦/.test(text)
  ) {

    addRiskHit({
      id: 'R_P2_TASTE_ABNORMAL',
      tag: 'TASTE_ABNORMAL',
      risk: 'P2',
      category: '口感体验',

      // 与真伪问题归入同一个 issueKey
      issueKey: 'AUTHENTICITY',
    });
  }


  // ==========================================================
  // 9. P3 — 建议型内容
  // ==========================================================

  if (
    /小包装/.test(text) ||
    /瓶口设计小一点/.test(text) ||
    /独立小袋装/.test(text)
  ) {

    addRiskHit({
      id: 'R_P3_SUGGESTION_PACKAGING',
      tag: 'SUGGESTION_PACKAGING',
      risk: 'P3',
      category: '包装问题',
      issueKey: 'SUGGESTION_PACKAGING',
    });
  }


  if (
    /巧克力味/.test(text) ||
    /其他口味/.test(text) ||
    /增加口味/.test(text)
  ) {

    addRiskHit({
      id: 'R_P3_SUGGESTION_FLAVOR',
      tag: 'SUGGESTION_FLAVOR',
      risk: 'P3',
      category: '口感体验',
      issueKey: 'SUGGESTION_FLAVOR',
    });
  }


  // ==========================================================
  // 10. Multi Issue（多问题）
  //
  // 同一句里出现两个真正不同的业务问题。
  // ==========================================================

  const distinctIssueKeys = new Set(
    riskHits.map(hit => hit.issueKey)
  );


  if (distinctIssueKeys.size >= 2) {

    pushUnique(
      metaTags,
      'MULTI_ISSUE'
    );
  }


  // ==========================================================
  // 11. 计算规则风险等级
  // ==========================================================

  let highestRiskHit = null;


  for (const hit of riskHits) {

    if (
      highestRiskHit === null ||
      RISK_SCORE[hit.risk] >
      RISK_SCORE[highestRiskHit.risk]
    ) {
      highestRiskHit = hit;
    }
  }


  let ruleRiskLevel =
    highestRiskHit?.risk ?? null;


  let ruleCategory =
    highestRiskHit?.category ?? null;


  let hardRiskHit =
    highestRiskHit
      ? riskHits.some(
          hit =>
            hit.risk === highestRiskHit.risk &&
            hit.hardRisk === true
        )
      : false;


  // ==========================================================
  // 12. Rating/Text Conflict
  //     （评分与文本冲突）
  //
  // 只检查 INITIAL_REVIEW。
  //
  // 追评沿用了首评评分，
  // 因此不能把追评和原始五星直接当成矛盾。
  // ==========================================================

  const productRating =
    numberOrNull(row.product_rating);


  const aliasCanonicals =
    getAliasCanonicals(row);


  const aliasSuggestsRisk =
    aliasCanonicals.some(
      value =>
        [
          '恶心',
          '头晕',
          '过敏',
          '假货',
          '密封',
        ].includes(value)
    );


  // 即使 Alias 没有被 Regex 识别，
  // 仍保留一个轻量 fallback。
  const hasAliasLiteral =
    /exin|tou\s*yun|guomin|seal/.test(text);


  const unresolvedNegativeExpression =
    /反胃得厉害|大家自己注意|感觉不对劲/.test(text);


  const conflictSignal =
    ['P0', 'P1', 'P2'].includes(
      ruleRiskLevel
    ) ||
    weakAuthenticityDoubt ||
    aliasSuggestsRisk ||
    hasAliasLiteral ||
    unresolvedNegativeExpression;


  if (
    row.content_type === 'INITIAL_REVIEW' &&
    productRating !== null &&
    productRating >= 4 &&
    conflictSignal
  ) {

    pushUnique(
      metaTags,
      'RATING_TEXT_CONFLICT'
    );

    pushUnique(
      matchedRuleIds,
      'R_META_RATING_TEXT_CONFLICT'
    );

    needAi = true;
  }


  // ==========================================================
  // 13. need_ai 决策
  // ==========================================================


  // 强/弱真伪质疑都需要 AI 补充语义判断
  if (
    strongAuthenticityDoubt ||
    weakAuthenticityDoubt
  ) {
    needAi = true;
  }


  // 拼音 / 英文混杂：
  // 代码发现了，但不完全信任
  if (
    aliasCanonicals.length > 0 ||
    hasAliasLiteral
  ) {
    needAi = true;
  }


  // 明确的归因不确定
  if (
    /(?:不确定|不知道)是不是这个原因/.test(text)
  ) {
    needAi = true;
  }


  // P0 同时存在多个业务问题时，
  // 交 AI 补充摘要与语义
  if (
    ruleRiskLevel === 'P0' &&
    metaTags.includes('MULTI_ISSUE')
  ) {
    needAi = true;
  }


  // ==========================================================
  // 14. Clear Positive / Closure
  //     （明确正面 / 明确闭环）
  //
  // 只有出现足够明确的正面信号，
  // 才允许规则直接给 NONE。
  //
  // 没匹配 ≠ NONE
  // ==========================================================

  const clearPositiveOrClosure =
    /回购/.test(text) ||
    /满意/.test(text) ||
    /不错/.test(text) ||
    /挺好/.test(text) ||
    /好喝/.test(text) ||
    /日期很新/.test(text) ||
    /第二次购买/.test(text) ||
    /第二次买/.test(text) ||
    /老客户/.test(text) ||
    /好吞咽/.test(text) ||
    /会一直喝/.test(text) ||
    /家里人一直在吃/.test(text) ||
    /舒服多了/.test(text) ||
    /放心了/.test(text) ||
    /会继续吃/.test(text) ||
    /密封膜是完整的/.test(text) ||
    /物流超快/.test(text) ||
    /包装严实/.test(text) ||
    /挺贴心/.test(text) ||
    /处理还算及时/.test(text) ||
    /已经寄回/.test(text) ||
    /补发.*日期新的/.test(text) ||
    /就当没事了/.test(text) ||
    /态度还行/.test(text) ||
    /没有出现漏液/.test(text) ||
    /没有出现恶心/.test(text) ||
    /没有不舒服/.test(text);


  // ==========================================================
  // 15. NONE / UNKNOWN 决策
  // ==========================================================

  let ruleDecision;


  if (ruleRiskLevel !== null) {

    ruleDecision = ruleRiskLevel;

  } else {

    const unresolvedSignal =
      weakAuthenticityDoubt ||
      aliasSuggestsRisk ||
      hasAliasLiteral ||
      unresolvedNegativeExpression;


    if (unresolvedSignal) {

      // UNKNOWN 不写进飞书 risk_level，
      // 只作为 n8n 临时决策。
      ruleDecision = 'UNKNOWN';
      ruleRiskLevel = null;
      needAi = true;

    } else if (
      hasNegationContext ||
      clearPositiveOrClosure
    ) {

      ruleDecision = 'NONE';
      ruleRiskLevel = 'NONE';
      needAi = false;

      pushUnique(
        matchedRuleIds,
        hasNegationContext
          ? 'R_NONE_NEGATION_CONTEXT'
          : 'R_NONE_CLEAR_POSITIVE'
      );

    } else {

      // 非空文本，但规则无法理解。
      //
      // 核心原则：
      // 没匹配 ≠ 没风险。
      ruleDecision = 'UNKNOWN';
      ruleRiskLevel = null;
      needAi = true;

      pushUnique(
        matchedRuleIds,
        'R_UNKNOWN_NO_DETERMINISTIC_MATCH'
      );
    }
  }


  // ==========================================================
  // 16. 组合 Rule Tags
  //
  // 顺序：
  // 业务标签
  // → 元信息标签
  // → 数据质量标签
  // ==========================================================

  const finalTags = [
    ...businessTags,
    ...metaTags,
    ...dataQualityTags,
  ];


  const ruleHit =
    matchedRuleIds.length > 0 ||
    finalTags.length > 0 ||
    ruleDecision === 'NONE';


  // ==========================================================
  // 17. 输出
  // ==========================================================

  let ruleReason;

  if (ruleDecision === 'UNKNOWN') {

    ruleReason =
      '确定性规则无法稳定完成风险定级，进入 AI 语义分析。';

  } else if (ruleDecision === 'NONE') {

    ruleReason =
      hasNegationContext
        ? '检测到明确否定语境，未发现有效风险。'
        : '检测到明确正面或已闭环表达，规则判断为无风险。';

  } else {

    ruleReason =
      `命中确定性规则，当前规则风险等级为 ${ruleDecision}。`;
  }


  return {
    analysis_scope: 'IN_SCOPE',
    skip_reason: null,

    rules_version: RULES_VERSION,

    rule_hit: ruleHit,
    rule_tags: finalTags,

    rule_risk_level: ruleRiskLevel,

    // n8n 内部使用
    rule_decision: ruleDecision,

    need_ai: needAi,

    // n8n 内部辅助字段
    rule_category: ruleCategory,
    matched_rule_ids: matchedRuleIds,
    hard_risk_hit: hardRiskHit,

    rule_reason: ruleReason,

    _rule_internal: {
      risk_hits: riskHits,
      data_quality_tags: dataQualityTags,
    },
  };
}


// ============================================================
// 18. First Pass（第一遍）
//     每条事件独立判断
// ============================================================

const evaluated = items.map(item => {

  const result =
    evaluateItem(item.json);

  return {
    json: {
      ...item.json,
      ...result,
    }
  };
});


// ============================================================
// 19. 建立首评索引
//
// content_id
// → INITIAL_REVIEW 分析结果
//
// 用于少量 Thread Context（线程上下文）。
// ============================================================

const initialByContentId = new Map();


for (const item of evaluated) {

  const row = item.json;

  if (
    row.content_type === 'INITIAL_REVIEW'
  ) {

    initialByContentId.set(
      row.content_id,
      row
    );
  }
}


// ============================================================
// 20. Second Pass（第二遍）
//     处理“确认上一条风险”的追评
//
// 示例：
// 首评：吃完恶心
// 追评：停了三天好多了，基本确定是这个的问题
//
// 追评虽然没有再次写“恶心”，
// 但在同一线程中属于风险确认。
// ============================================================

for (const item of evaluated) {

  const row = item.json;

  if (
    row.content_type !== 'FOLLOWUP_REVIEW'
  ) {
    continue;
  }


  if (
    row.rule_decision !== 'UNKNOWN'
  ) {
    continue;
  }


  const text = textOf(row);


  const confirmsPreviousIssue =
    /基本确定是这个的问题/.test(text) ||
    /停了[^。！？，,]*(?:好多了|好了)/.test(text) ||
    /以后不敢吃/.test(text);


  if (!confirmsPreviousIssue) {
    continue;
  }


  const root =
    initialByContentId.get(
      row.root_review_id
    );


  if (!root) {
    continue;
  }


  if (
    !['P0', 'P1'].includes(
      root.rule_risk_level
    )
  ) {
    continue;
  }


  const rootRiskHits =
    root._rule_internal?.risk_hits ?? [];


  const inheritedRiskTags =
    rootRiskHits
      .filter(
        hit =>
          hit.risk ===
          root.rule_risk_level
      )
      .map(hit => hit.tag);


  const dataQualityTags =
    row._rule_internal
      ?.data_quality_tags ?? [];


  row.rule_tags = [
    ...new Set([
      ...inheritedRiskTags,
      ...dataQualityTags,
    ])
  ];


  row.rule_risk_level =
    root.rule_risk_level;


  row.rule_decision =
    root.rule_risk_level;


  row.rule_category =
    root.rule_category;


  row.hard_risk_hit =
    root.hard_risk_hit;


  row.rule_hit = true;


  // 追评已经进一步确认此前问题，
  // 当前测试设计中不必再次调用 AI。
  row.need_ai = false;


  row.matched_rule_ids = [
    ...new Set([
      ...(row.matched_rule_ids ?? []),
      'R_THREAD_CONFIRMATION_INHERIT',
    ])
  ];


  row.rule_reason =
    '追评明确确认或延续首评中的高风险问题，继承同一评价线程的风险判断。';
}


// ============================================================
// 21. 删除内部临时计算对象
//
// _rule_internal 只是节点内部使用，
// 不继续往后传。
// ============================================================

return evaluated.map(item => {

  const {
    _rule_internal,
    ...cleanJson
  } = item.json;

  return {
    json: cleanJson
  };
});

// ============================================================
// Prepare Dify Payload v1.0
//
// 职责：
// 1. 只接收 AI_REQUIRED 分支的数据
// 2. 保留 PostgreSQL / n8n 后续需要的追踪字段
// 3. 把 Dify 需要的 9 个业务变量整理好
// 4. 将 rule_tags 数组序列化为 JSON 字符串
//
// 不负责：
// - 调用 Dify
// - AI 判断
// - Final Decision
// ============================================================

const items = $input.all();

const output = [];


// ============================================================
// 工具函数
// ============================================================

function safeString(value) {
  if (value === undefined || value === null) {
    return '';
  }

  return String(value);
}


// ------------------------------------------------------------
// AI 调用追踪 ID
//
// 旧版本：
// source_row_no__INITIAL
//
// 新 PostgreSQL Canonical 架构：
// RAW_<raw_id>_<事件类型>
//
// 示例：
// RAW_2_INITIAL
// RAW_3_FOLLOWUP
//
// 注意：
// ai_case_id 只是 n8n / Dify 调用链追踪 ID。
// 真正的业务唯一键仍然是 content_key。
// ------------------------------------------------------------

function buildCaseId(row) {

  let slot = row.content_type;

  if (row.content_type === 'INITIAL_REVIEW') {
    slot = 'INITIAL';
  }

  if (row.content_type === 'FOLLOWUP_REVIEW') {
    slot = 'FOLLOWUP';
  }

  if (row.content_type === 'BUYER_REPLY') {
    slot = 'BUYER_REPLY';
  }

  if (row.content_type === 'SELLER_REPLY') {
    slot = 'SELLER_REPLY';
  }

  if (row.content_type === 'PUBLIC_COMMENT') {
    slot = 'PUBLIC_COMMENT';
  }

  // raw_id 在当前 PostgreSQL Canonical 架构中必须存在。
  // 不允许继续生成 undefined__INITIAL 这类追踪 ID。
  if (
    row.raw_id === undefined ||
    row.raw_id === null ||
    row.raw_id === ''
  ) {
    throw new Error(
      `Prepare Dify Payload v1.0: 缺少 raw_id，无法生成 ai_case_id，content_key=${row.content_key}`
    );
  }

  return `RAW_${row.raw_id}_${slot}`;
}


// ============================================================
// 主处理
// ============================================================

for (const item of items) {

  const row = item.json;


  // ----------------------------------------------------------
  // 1. 防御性检查
  //
  // 这个节点理论上只应该接 AI_REQUIRED。
  // ----------------------------------------------------------

  if (row.analysis_scope !== 'IN_SCOPE') {
    throw new Error(
      `Prepare Dify Payload v1.0: 收到非 IN_SCOPE 数据，content_key=${row.content_key}`
    );
  }


  if (row.need_ai !== true) {
    throw new Error(
      `Prepare Dify Payload v1.0: 收到 need_ai != true 的数据，content_key=${row.content_key}`
    );
  }


  // ----------------------------------------------------------
  // 2. rule_tags 序列化
  //
  // Serialization（序列化）：
  // 把数组转换成 JSON 字符串，方便跨系统传输。
  // ----------------------------------------------------------

  const ruleTagsJson =
    JSON.stringify(
      Array.isArray(row.rule_tags)
        ? row.rule_tags
        : []
    );


  // ----------------------------------------------------------
  // 3. 生成 AI 调用追踪 ID
  //
  // 示例：
  // RAW_2_INITIAL
  // RAW_3_FOLLOWUP
  //
  // 不传给模型，只用于 n8n 后续追踪和请求/响应对账。
  // ----------------------------------------------------------

  const aiCaseId =
    buildCaseId(row);


  // ----------------------------------------------------------
  // 4. 输出
  // ----------------------------------------------------------

  output.push({
    json: {

      // ======================================================
      // A. n8n / PostgreSQL Tracking Metadata（追踪元数据）
      // ======================================================

      raw_id:
        row.raw_id,

      source_staging_id:
        row.source_staging_id ?? null,

      ai_case_id:
        aiCaseId,

      // 暂时保留，兼容旧测试/排查。
      // 新架构不再依赖它生成 ai_case_id。
      source_row_no:
        row.source_row_no ?? null,

      content_key:
        row.content_key,

      content_id:
        row.content_id,

      root_review_id:
        row.root_review_id,

      parent_content_id:
        row.parent_content_id ?? null,

      content_type:
        row.content_type,

      platform:
        row.platform,

      shop_id:
        row.shop_id ?? null,

      shop_name:
        row.shop_name,

      product_id:
        row.product_id,

      product_name:
        row.product_name,

      sku_id:
        row.sku_id ?? null,

      sku_name:
        row.sku_name ?? null,

      source_review_id:
        row.source_review_id ?? null,

      rule_risk_level_original:
        row.rule_risk_level,

      rule_decision_original:
        row.rule_decision,

      hard_risk_hit_original:
        row.hard_risk_hit,


      // ======================================================
      // B. Dify Inputs
      //
      // 这 9 个字段与 Dify Start 节点完全对应。
      // 不要随意改字段名。
      // ======================================================

      dify_inputs: {

        content_text:
          safeString(row.content_text),

        content_type:
          safeString(row.content_type),

        product_name:
          safeString(row.product_name),

        product_rating:
          row.product_rating ?? null,

        rating_label:
          safeString(row.rating_label),

        rule_tags_json:
          ruleTagsJson,

        rule_risk_level:
          safeString(row.rule_risk_level),

        rule_decision:
          safeString(row.rule_decision),

        hard_risk_hit:
          String(row.hard_risk_hit),
      }
    }
  });
}


return output;

// ============================================================
// Normalize Dify Response v1.0
//
// 职责：
// 1. 解析 Dify Workflow API 返回结果
// 2. 恢复 PostgreSQL / n8n Tracking Metadata（追踪信息）
// 3. 提取 AI 分析结果
// 4. 提取 workflow_run_id / elapsed_time / token usage（如有）
// 5. 为后续 Final Decision 提供统一结构
// ============================================================


// 当前 HTTP Request 返回的数据
const response = $json;


// ============================================================
// 1. 找回对应的原始请求数据
//
// n8n Item Linking（数据项关联）允许下游节点
// 找到这一条 Dify Response 对应的
// Prepare Dify Payload item。
// ============================================================

const source =
  $('Prepare Dify Payload v1.0').item.json;


// ============================================================
// 2. 基础结构提取
// ============================================================

const data =
  response.data ?? {};

const outputs =
  data.outputs ?? {};


// ============================================================
// 3. Workflow 调用是否成功
// ============================================================

const workflowSucceeded =
  data.status === 'succeeded';

const validationSucceeded =
  outputs.validation_status === 'SUCCESS';


// ============================================================
// 4. 统一状态
// ============================================================

let aiCallStatus;

if (!workflowSucceeded) {

  aiCallStatus =
    'WORKFLOW_ERROR';

} else if (!validationSucceeded) {

  aiCallStatus =
    'VALIDATION_ERROR';

} else {

  aiCallStatus =
    'SUCCESS';
}


// ============================================================
// 5. Performance（性能）
// ============================================================

const elapsedTime =
  data.elapsed_time ?? null;

const latencyMs =
  typeof elapsedTime === 'number'
    ? Math.round(elapsedTime * 1000)
    : null;


// ============================================================
// 6. rule_tags 恢复
//
// Prepare Dify Payload 中为了传输给 Dify，
// rule_tags 已被序列化成 JSON 字符串。
// 这里重新恢复成数组，供 Final Decision / Analysis Record 使用。
// ============================================================

let ruleTags = [];

try {

  const rawRuleTags =
    source?.dify_inputs?.rule_tags_json;

  if (rawRuleTags) {
    const parsed =
      JSON.parse(rawRuleTags);

    if (Array.isArray(parsed)) {
      ruleTags = parsed;
    }
  }

} catch (error) {

  ruleTags = [];
}


// ============================================================
// 7. 输出统一结构
// ============================================================

return {
  json: {

    // ========================================================
    // A. PostgreSQL / n8n Correlation Metadata
    // ========================================================

    raw_id:
      source.raw_id ?? null,

    source_staging_id:
      source.source_staging_id ?? null,

    ai_case_id:
      source.ai_case_id ?? null,

    source_row_no:
      source.source_row_no ?? null,

    content_key:
      source.content_key,

    content_id:
      source.content_id,

    root_review_id:
      source.root_review_id,

    parent_content_id:
      source.parent_content_id ?? null,

    content_type:
      source.content_type,

    source_review_id:
      source.source_review_id ?? null,


    // ========================================================
    // B. Business Metadata
    // ========================================================

    platform:
      source.platform ?? null,

    shop_id:
      source.shop_id ?? null,

    shop_name:
      source.shop_name ?? null,

    product_id:
      source.product_id ?? null,

    product_name:
      source.product_name ?? null,

    sku_id:
      source.sku_id ?? null,

    sku_name:
      source.sku_name ?? null,


    // ========================================================
    // C. 原 Rule Engine 结果
    // ========================================================

    rule_hit:
      true,

    rule_tags:
      ruleTags,

    rule_risk_level:
      source.rule_risk_level_original ?? null,

    rule_decision:
      source.rule_decision_original ?? null,

    hard_risk_hit:
      source.hard_risk_hit_original ?? false,


    // ========================================================
    // D. AI 调用状态
    // ========================================================

    ai_called:
      true,

    ai_call_status:
      aiCallStatus,

    ai_validation_status:
      outputs.validation_status ?? null,

    dify_task_id:
      response.task_id ?? null,

    dify_workflow_run_id:
      response.workflow_run_id
      ?? data.id
      ?? null,

    dify_status:
      data.status ?? null,


    // ========================================================
    // E. AI 分析结果
    // ========================================================

    ai_category:
      outputs.category ?? null,

    ai_subcategory:
      outputs.subcategory ?? null,

    ai_sentiment:
      outputs.sentiment ?? null,

    ai_risk_level:
      outputs.risk_level ?? null,

    ai_summary:
      outputs.summary ?? null,

    confidence:
      outputs.confidence ?? null,

    ai_error_message:
      outputs.error_message ?? null,

    ai_raw_output:
      outputs.raw_output ?? null,


    // ========================================================
    // F. Model / Version
    // ========================================================

    model_name:
      'DeepSeek V4.1 Flash',

    prompt_version:
      'review-v1.0',


    // ========================================================
    // G. Performance
    //
    // 当前 Dify API 能提供 total_tokens，
    // 但没有稳定返回 input/output 拆分。
    // 所以：
    // - total_tokens：真实值
    // - input_tokens / output_tokens：NULL
    // ========================================================

    input_tokens:
      null,

    output_tokens:
      null,

    total_tokens:
      data.total_tokens ?? null,

    elapsed_time:
      elapsedTime,

    latency_ms:
      latencyMs,
  }
};

// ============================================================
// Final Decision Engine v1.0
//
// 职责：
// 1. 合并 Rule Engine 与 AI 的风险判断
// 2. 确定 final_* 业务结果
// 3. 防止 AI 降级明确的规则风险
// 4. AI 失败时允许确定性规则兜底
// 5. 标记规则 / AI 冲突是否需要人工复核
//
// 当前节点仅处理 AI_REQUIRED 分支。
// RULE_ONLY / OUT_OF_SCOPE 后面分别处理。
// ============================================================

const row = $json;


// ============================================================
// 1. Risk Vocabulary（风险等级定义）
// ============================================================

const RISK_SCORE = {
  NONE: 0,
  P3: 1,
  P2: 2,
  P1: 3,
  P0: 4,
};

const VALID_RISKS = new Set([
  'NONE',
  'P3',
  'P2',
  'P1',
  'P0',
]);


function normalizeRisk(value) {

  if (
    value === undefined ||
    value === null ||
    value === ''
  ) {
    return null;
  }

  const risk =
    String(value).trim().toUpperCase();

  return VALID_RISKS.has(risk)
    ? risk
    : null;
}


function higherRisk(a, b) {

  const riskA = normalizeRisk(a);
  const riskB = normalizeRisk(b);

  if (riskA === null) {
    return riskB;
  }

  if (riskB === null) {
    return riskA;
  }

  return RISK_SCORE[riskA] >= RISK_SCORE[riskB]
    ? riskA
    : riskB;
}


// ============================================================
// 2. 输入标准化
// ============================================================

const ruleRisk =
  normalizeRisk(row.rule_risk_level);

const aiRisk =
  normalizeRisk(row.ai_risk_level);

const ruleDecision =
  row.rule_decision
    ? String(row.rule_decision).toUpperCase()
    : null;

const aiSucceeded =
  row.ai_call_status === 'SUCCESS' &&
  row.ai_validation_status === 'SUCCESS';


// 规则是否真正提供了风险判断
//
// P0~P3 = 有风险结论
// NONE  = 明确无风险
// UNKNOWN / null = 规则无法判断
const ruleHasDecision =
  ruleRisk !== null;


// 规则是否提供了“风险下限”
//
// NONE 不属于风险下限。
// P0~P3 才属于。
const ruleHasRiskFloor =
  ruleRisk !== null &&
  ruleRisk !== 'NONE';


// ============================================================
// 3. Final Risk Level（最终风险等级）
// ============================================================

let finalRiskLevel = null;
let decisionSource = null;
let manualReviewRequired = false;

let decisionReason = '';


// ------------------------------------------------------------
// Case A：AI 成功
// ------------------------------------------------------------

if (aiSucceeded) {

  // 规则已有明确风险 P0~P3：
  // 最终取 Rule / AI 中更严重者。
  if (ruleHasRiskFloor) {

    finalRiskLevel =
      higherRisk(ruleRisk, aiRisk);

    decisionSource =
      'RULE+AI';

    decisionReason =
      `规则风险=${ruleRisk}，AI风险=${aiRisk}，最终取更高风险=${finalRiskLevel}`;


    // Rule 和 AI 不一致时标记人工复核。
    if (ruleRisk !== aiRisk) {
      manualReviewRequired = true;
    }

  }

  // Rule NONE / UNKNOWN / null：
  // 风险判断主要交给 AI。
  else {

    finalRiskLevel =
      aiRisk;

    decisionSource =
      'AI';

    decisionReason =
      `规则未形成风险下限（${ruleDecision ?? ruleRisk ?? 'UNKNOWN'}），采用AI风险=${aiRisk}`;
  }

}


// ------------------------------------------------------------
// Case B：AI 失败
// ------------------------------------------------------------

else {

  manualReviewRequired = true;


  // Rule 至少给出了明确结果
  if (ruleHasDecision) {

    finalRiskLevel =
      ruleRisk;

    decisionSource =
      'RULE';

    decisionReason =
      `AI未成功完成分析，使用规则结果=${ruleRisk}兜底`;
  }

  // Rule 本身也是 UNKNOWN
  else {

    finalRiskLevel =
      null;

    decisionSource =
      null;

    decisionReason =
      '规则无法完成判断，AI分析也未成功，无法生成最终风险等级';
  }
}


// ============================================================
// 4. Final Semantic Result（最终语义结果）
//
// AI 成功时：
// category / sentiment / summary 使用 AI 结果。
//
// AI 失败时：
// 不编造语义字段，保持 null。
// ============================================================

const finalCategory =
  aiSucceeded
    ? row.ai_category
    : null;

const finalSubcategory =
  aiSucceeded
    ? row.ai_subcategory
    : null;

const finalSentiment =
  aiSucceeded
    ? row.ai_sentiment
    : null;

const finalSummary =
  aiSucceeded
    ? row.ai_summary
    : null;


// ============================================================
// 5. Analysis Status（分析状态）
// ============================================================

let analysisStatus;

if (aiSucceeded) {

  analysisStatus = 'SUCCESS';

} else {

  analysisStatus = 'ERROR';
}


// ============================================================
// 6. 输出
// ============================================================

return {
  json: {

    // 保留前面所有数据
    ...row,


    // --------------------------------------------------------
    // Final Decision
    // --------------------------------------------------------

    final_category:
      finalCategory,

    final_subcategory:
      finalSubcategory,

    final_sentiment:
      finalSentiment,

    final_risk_level:
      finalRiskLevel,

    final_summary:
      finalSummary,

    decision_source:
      decisionSource,


    // --------------------------------------------------------
    // Status
    // --------------------------------------------------------

    analysis_status:
      analysisStatus,

    manual_review_required:
      manualReviewRequired,


    // --------------------------------------------------------
    // Internal Debug / Explainability
    //
    // 当前只在 n8n 内部使用，
    // AI_Analysis 表目前没有该字段。
    // --------------------------------------------------------

    final_decision_reason:
      decisionReason,


    // --------------------------------------------------------
    // Conflict Indicator
    // --------------------------------------------------------

    risk_conflict:
      (
        aiSucceeded &&
        ruleHasRiskFloor &&
        ruleRisk !== aiRisk
      )
  }
};

// ============================================================
// Build AI Analysis Record - AI Path v1.0
//
// 职责：
// 将 AI_REQUIRED 分支经过 Final Decision 后的结果
// 映射成 AI_Analysis 表 V1 的正式 34 字段结构。
//
// 输入：
// Final Decision Engine v1.0
//
// 输出：
// 与飞书 AI_Analysis V1 Schema 对齐的 34 个字段
//
// 当前仅处理：
// analysis_scope = IN_SCOPE
// need_ai = true
// ============================================================

const row = $json;


// ============================================================
// 1. Rule Tags（规则标签）标准化
//
// Final Decision 现在已经保留 rule_tags 数组，
// 所以不再反向依赖 Prepare Dify Payload。
// ============================================================

const ruleTagsArray =
  Array.isArray(row.rule_tags)
    ? row.rule_tags
    : [];

const ruleTagsJson =
  JSON.stringify(ruleTagsArray);


// ============================================================
// 2. Rule Hit
//
// 优先使用上游真实 rule_hit。
// 如果上游没有该字段，再根据 rule_tags 做兜底。
// ============================================================

const ruleHit =
  typeof row.rule_hit === 'boolean'
    ? row.rule_hit
    : ruleTagsArray.length > 0;


// ============================================================
// 3. Version（版本）
//
// rules_version 不再硬编码 rules-v1.0。
// 当前同一次 execution 中所有 Rule Engine item
// 使用同一个规则版本，因此读取本次 Rule Engine 的真实版本。
// ============================================================

const ruleEngineFirstItem =
  $('Rule Engine v1.0').first().json;

const rulesVersion =
  ruleEngineFirstItem.rules_version ?? null;

if (!rulesVersion) {
  throw new Error(
    `Build AI Analysis Record - AI Path v1.0: 无法获取 rules_version，content_key=${row.content_key}`
  );
}


// prompt / model 优先使用当前实际 AI 调用链传下来的版本。

const promptVersion =
  row.prompt_version ?? null;

const modelName =
  row.model_name ?? null;

if (!promptVersion) {
  throw new Error(
    `Build AI Analysis Record - AI Path v1.0: 缺少 prompt_version，content_key=${row.content_key}`
  );
}

if (!modelName) {
  throw new Error(
    `Build AI Analysis Record - AI Path v1.0: 缺少 model_name，content_key=${row.content_key}`
  );
}


// ============================================================
// 4. Analysis Identity（分析记录身份）
//
// analysis_run_id：
// 同一次 n8n execution 共用，用于批次追踪。
//
// analysis_id：
// 每一条分析记录唯一。
// ============================================================

const executionId =
  String($execution.id);

const analysisRunId =
  `N8N_${executionId}`;

const analysisId =
  `AN_${executionId}_${row.ai_case_id}`;

const analyzedAt =
  new Date().toISOString();


// ============================================================
// 5. Token Usage
//
// 当前只能稳定获得 total_tokens。
// input_tokens / output_tokens 拿不到时必须保持 null，
// 不能伪造为 0。
// ============================================================

const inputTokens =
  (
    typeof row.input_tokens === 'number'
    && Number.isFinite(row.input_tokens)
  )
    ? Math.round(row.input_tokens)
    : null;

const outputTokens =
  (
    typeof row.output_tokens === 'number'
    && Number.isFinite(row.output_tokens)
  )
    ? Math.round(row.output_tokens)
    : null;

const totalTokens =
  (
    typeof row.total_tokens === 'number'
    && Number.isFinite(row.total_tokens)
  )
    ? Math.round(row.total_tokens)
    : null;


// ============================================================
// 6. Latency（延迟）
//
// 优先使用 Normalize Dify Response 已经计算好的 latency_ms。
// 若不存在，再用 elapsed_time × 1000 兜底。
// ============================================================

let latencyMs = null;

if (
  typeof row.latency_ms === 'number'
  && Number.isFinite(row.latency_ms)
) {

  latencyMs =
    Math.round(row.latency_ms);

} else if (
  typeof row.elapsed_time === 'number'
  && Number.isFinite(row.elapsed_time)
) {

  latencyMs =
    Math.round(row.elapsed_time * 1000);
}


// ============================================================
// 7. AI Called
//
// 能进入 AI Path，说明已经实际调用过 Dify。
// 即使最终 validation ERROR，也仍然是 true。
// ============================================================

const aiCalled =
  true;


// ============================================================
// 8. Error Message
//
// SUCCESS → null
// ERROR → 使用 AI / Workflow 返回的错误信息
// ============================================================

let errorMessage =
  null;

if (row.analysis_status === 'ERROR') {

  errorMessage =
    row.ai_error_message
    || (
      row.dify_status
        ? `Dify status=${row.dify_status}`
        : 'AI analysis failed'
    );
}


// ============================================================
// 9. 输出 AI_Analysis 正式 34 字段
//
// ⚠️ 不额外加入 raw_id / source_staging_id。
// PostgreSQL 状态回写后续使用 content_key。
// ============================================================

return {
  json: {

    // --------------------------------------------------------
    // Group 1
    // Association / Version
    // --------------------------------------------------------

    analysis_id:
      analysisId,

    content_key:
      row.content_key,

    analysis_run_id:
      analysisRunId,

    analyzed_at:
      analyzedAt,

    rules_version:
      rulesVersion,

    prompt_version:
      promptVersion,

    is_current:
      true,


    // --------------------------------------------------------
    // Group 2
    // Rule Engine
    // --------------------------------------------------------

    rule_hit:
      ruleHit,

    rule_tags:
      ruleTagsJson,

    rule_risk_level:
      row.rule_risk_level ?? null,

    need_ai:
      true,


    // --------------------------------------------------------
    // Group 3
    // AI Result
    // --------------------------------------------------------

    ai_called:
      aiCalled,

    model_name:
      modelName,

    ai_category:
      row.ai_category ?? null,

    ai_subcategory:
      row.ai_subcategory ?? null,

    ai_sentiment:
      row.ai_sentiment ?? null,

    ai_risk_level:
      row.ai_risk_level ?? null,

    ai_summary:
      row.ai_summary ?? null,

    confidence:
      (
        typeof row.confidence === 'number'
        && Number.isFinite(row.confidence)
      )
        ? row.confidence
        : null,


    // --------------------------------------------------------
    // Group 4
    // Final Decision
    // --------------------------------------------------------

    final_category:
      row.final_category ?? null,

    final_subcategory:
      row.final_subcategory ?? null,

    final_sentiment:
      row.final_sentiment ?? null,

    final_risk_level:
      row.final_risk_level ?? null,

    final_summary:
      row.final_summary ?? null,

    decision_source:
      row.decision_source ?? null,


    // --------------------------------------------------------
    // Group 5
    // Usage / Performance
    // --------------------------------------------------------

    input_tokens:
      inputTokens,

    output_tokens:
      outputTokens,

    total_tokens:
      totalTokens,

    latency_ms:
      latencyMs,


    // --------------------------------------------------------
    // Group 6
    // Scope / Status / Error
    // --------------------------------------------------------

    analysis_scope:
      'IN_SCOPE',

    analysis_status:
      row.analysis_status,

    skip_reason:
      null,

    manual_review_required:
      row.manual_review_required === true,

    error_message:
      errorMessage
  }
};

// ============================================================
// Build AI Analysis Record - Rule Only Path v1.0
//
// 职责：
// 将 RULE_ONLY 分支的数据整理成
// AI_Analysis V1 正式 34 字段。
//
// 特点：
// - 不调用 AI
// - Token = 0
// - Final Risk 直接使用规则结果
// - decision_source = RULE
//
// 注意：
// 规则没有提供的语义字段绝不编造。
// ============================================================

const row = $json;


// ============================================================
// 1. 基础校验
// ============================================================

if (row.analysis_scope !== 'IN_SCOPE') {
  throw new Error(
    `Rule Only Builder: 收到非 IN_SCOPE 数据，content_key=${row.content_key}`
  );
}

if (row.need_ai !== false) {
  throw new Error(
    `Rule Only Builder: 收到 need_ai != false 的数据，content_key=${row.content_key}`
  );
}


// ============================================================
// 2. PostgreSQL Canonical Identity
//
// 新架构不再依赖 source_row_no。
// 使用 raw_id + content_type 生成稳定的本次分析记录 ID。
// ============================================================

if (
  row.raw_id === undefined ||
  row.raw_id === null ||
  row.raw_id === ''
) {
  throw new Error(
    `Rule Only Builder: 缺少 raw_id，无法生成 analysis_id，content_key=${row.content_key}`
  );
}

let slot =
  row.content_type ?? 'UNKNOWN';

if (row.content_type === 'INITIAL_REVIEW') {
  slot = 'INITIAL';
}

if (row.content_type === 'FOLLOWUP_REVIEW') {
  slot = 'FOLLOWUP';
}

if (row.content_type === 'BUYER_REPLY') {
  slot = 'BUYER_REPLY';
}

if (row.content_type === 'SELLER_REPLY') {
  slot = 'SELLER_REPLY';
}

if (row.content_type === 'PUBLIC_COMMENT') {
  slot = 'PUBLIC_COMMENT';
}


// ============================================================
// 3. Analysis Identity（分析记录身份）
// ============================================================

const executionId =
  String($execution.id);

const analysisRunId =
  `N8N_${executionId}`;

const analysisId =
  `AN_${executionId}_RAW_${row.raw_id}_${slot}`;

const analyzedAt =
  new Date().toISOString();


// ============================================================
// 4. Rules Version（规则版本）
//
// 优先读取当前 item 自己携带的真实版本。
// 若当前 item 没有，再从本次 Rule Engine execution 获取。
// 不再硬编码 rules-v1.0。
// ============================================================

const ruleEngineFirstItem =
  $('Rule Engine v1.0').first().json;

const rulesVersion =
  row.rules_version
  ?? ruleEngineFirstItem.rules_version
  ?? null;

if (!rulesVersion) {
  throw new Error(
    `Rule Only Builder: 无法获取 rules_version，content_key=${row.content_key}`
  );
}


// ============================================================
// 5. Rule Tags 标准化
//
// Rule Engine 可能输出：
// - rule_tags 数组
// - JSON 字符串
//
// AI_Analysis 表要求保存 JSON 数组字符串。
// ============================================================

let ruleTagsArray = [];

if (Array.isArray(row.rule_tags)) {

  ruleTagsArray =
    row.rule_tags;

} else if (
  typeof row.rule_tags === 'string'
  && row.rule_tags.trim() !== ''
) {

  try {

    const parsed =
      JSON.parse(row.rule_tags);

    ruleTagsArray =
      Array.isArray(parsed)
        ? parsed
        : [];

  } catch {

    // 如果不是合法 JSON，但确实有文本，
    // 作为单个 tag 保留。
    ruleTagsArray = [
      row.rule_tags
    ];
  }
}

const ruleTagsJson =
  JSON.stringify(ruleTagsArray);


// ============================================================
// 6. Rule Hit
//
// 优先使用上游明确给出的 rule_hit。
// 没有时，再使用 matched_rule_ids / rule_tags 兜底。
// ============================================================

const ruleHit =
  typeof row.rule_hit === 'boolean'
    ? row.rule_hit
    : (
        ruleTagsArray.length > 0
        ||
        (
          Array.isArray(row.matched_rule_ids)
          && row.matched_rule_ids.length > 0
        )
      );


// ============================================================
// 7. Final Risk
//
// RULE_ONLY 的核心：
// 不经过 AI，最终风险直接采用规则结果。
// ============================================================

const finalRiskLevel =
  row.rule_risk_level ?? null;


// ============================================================
// 8. Final Semantic Fields
//
// 只有 Rule Engine 真正提供了对应字段时才使用。
// 不能在这里重新做语义推断。
// ============================================================

const finalCategory =
  row.rule_category ?? null;

const finalSubcategory =
  row.rule_subcategory ?? null;

const finalSentiment =
  row.rule_sentiment ?? null;


// Summary 优先使用规则已经生成的 rule_summary。
// 如果没有，再退回 rule_reason。

const finalSummary =
  row.rule_summary
  ?? row.rule_reason
  ?? null;


// ============================================================
// 9. Analysis Status
// ============================================================

const analysisStatus =
  finalRiskLevel !== null
    ? 'SUCCESS'
    : 'ERROR';

const manualReviewRequired =
  analysisStatus === 'ERROR';

let errorMessage =
  null;

if (analysisStatus === 'ERROR') {
  errorMessage =
    'RULE_ONLY 分支未获得有效 rule_risk_level';
}


// ============================================================
// 10. 输出 AI_Analysis 正式 34 字段
//
// 注意：
// Rule Only 没有调用 AI，因此：
// - prompt_version = null
// - model_name = null
// - AI semantic fields = null
// - token = 0
// - latency_ms = null
// ============================================================

return {
  json: {

    // --------------------------------------------------------
    // Group 1
    // Association / Version
    // --------------------------------------------------------

    analysis_id:
      analysisId,

    content_key:
      row.content_key,

    analysis_run_id:
      analysisRunId,

    analyzed_at:
      analyzedAt,

    rules_version:
      rulesVersion,

    prompt_version:
      null,

    is_current:
      true,


    // --------------------------------------------------------
    // Group 2
    // Rule Engine
    // --------------------------------------------------------

    rule_hit:
      ruleHit,

    rule_tags:
      ruleTagsJson,

    rule_risk_level:
      row.rule_risk_level ?? null,

    need_ai:
      false,


    // --------------------------------------------------------
    // Group 3
    // AI Result
    // --------------------------------------------------------

    ai_called:
      false,

    model_name:
      null,

    ai_category:
      null,

    ai_subcategory:
      null,

    ai_sentiment:
      null,

    ai_risk_level:
      null,

    ai_summary:
      null,

    confidence:
      null,


    // --------------------------------------------------------
    // Group 4
    // Final Decision
    // --------------------------------------------------------

    final_category:
      finalCategory,

    final_subcategory:
      finalSubcategory,

    final_sentiment:
      finalSentiment,

    final_risk_level:
      finalRiskLevel,

    final_summary:
      finalSummary,

    decision_source:
      'RULE',


    // --------------------------------------------------------
    // Group 5
    // Usage / Performance
    //
    // 这里的 0 是真实的 0：
    // AI 根本没有被调用。
    // --------------------------------------------------------

    input_tokens:
      0,

    output_tokens:
      0,

    total_tokens:
      0,

    // 没有 AI 调用，
    // 所以不存在 AI latency。
    latency_ms:
      null,


    // --------------------------------------------------------
    // Group 6
    // Scope / Status
    // --------------------------------------------------------

    analysis_scope:
      'IN_SCOPE',

    analysis_status:
      analysisStatus,

    skip_reason:
      null,

    manual_review_required:
      manualReviewRequired,

    error_message:
      errorMessage
  }
};

// ============================================================
// Build AI Analysis Record - Out Of Scope Path v1.0
//
// 职责：
// 将 OUT_OF_SCOPE 分支的数据整理成
// AI_Analysis V1 正式 34 字段。
//
// 核心语义：
// - 不属于本次分析范围
// - 不调用 AI
// - analysis_status = SKIPPED
// - 不生成 final 风险结论
//
// 注意：
// OUT_OF_SCOPE ≠ NONE
//
// NONE:
// 已完成分析，并明确判断无风险
//
// OUT_OF_SCOPE:
// 根本不进入正式风险分析
// ============================================================

const row = $json;


// ============================================================
// 1. 基础校验
// ============================================================

if (row.analysis_scope !== 'OUT_OF_SCOPE') {
  throw new Error(
    `Out Of Scope Builder: 收到非 OUT_OF_SCOPE 数据，content_key=${row.content_key}`
  );
}


// ============================================================
// 2. PostgreSQL Canonical Identity
//
// 新架构不再依赖 source_row_no。
// 使用 raw_id + content_type 生成本次 analysis_id。
// ============================================================

if (
  row.raw_id === undefined ||
  row.raw_id === null ||
  row.raw_id === ''
) {
  throw new Error(
    `Out Of Scope Builder: 缺少 raw_id，无法生成 analysis_id，content_key=${row.content_key}`
  );
}

let slot =
  row.content_type ?? 'UNKNOWN';

if (row.content_type === 'INITIAL_REVIEW') {
  slot = 'INITIAL';
}

if (row.content_type === 'FOLLOWUP_REVIEW') {
  slot = 'FOLLOWUP';
}

if (row.content_type === 'BUYER_REPLY') {
  slot = 'BUYER_REPLY';
}

if (row.content_type === 'SELLER_REPLY') {
  slot = 'SELLER_REPLY';
}

if (row.content_type === 'PUBLIC_COMMENT') {
  slot = 'PUBLIC_COMMENT';
}


// ============================================================
// 3. Analysis Identity
// ============================================================

const executionId =
  String($execution.id);

const analysisRunId =
  `N8N_${executionId}`;

const analysisId =
  `AN_${executionId}_RAW_${row.raw_id}_${slot}`;

const analyzedAt =
  new Date().toISOString();


// ============================================================
// 4. Rules Version
//
// 优先使用当前 item 自己携带的版本。
// 若没有，再从本次 Rule Engine execution 读取。
// ============================================================

const ruleEngineFirstItem =
  $('Rule Engine v1.0').first().json;

const rulesVersion =
  row.rules_version
  ?? ruleEngineFirstItem.rules_version
  ?? null;

if (!rulesVersion) {
  throw new Error(
    `Out Of Scope Builder: 无法获取 rules_version，content_key=${row.content_key}`
  );
}


// ============================================================
// 5. Rule Tags 标准化
//
// 如果 Rule Engine 已产生 rule_tags，就忠实保留。
// 没有则写 []。
// ============================================================

let ruleTagsArray = [];

if (Array.isArray(row.rule_tags)) {

  ruleTagsArray =
    row.rule_tags;

} else if (
  typeof row.rule_tags === 'string'
  && row.rule_tags.trim() !== ''
) {

  try {

    const parsed =
      JSON.parse(row.rule_tags);

    ruleTagsArray =
      Array.isArray(parsed)
        ? parsed
        : [];

  } catch {

    ruleTagsArray = [
      row.rule_tags
    ];
  }
}

const ruleTagsJson =
  JSON.stringify(ruleTagsArray);


// ============================================================
// 6. Rule Hit
//
// 优先使用上游已经明确给出的 rule_hit。
// 如果没有，再使用 tags / matched_rule_ids 兜底。
// ============================================================

const ruleHit =
  typeof row.rule_hit === 'boolean'
    ? row.rule_hit
    : (
        ruleTagsArray.length > 0
        ||
        (
          Array.isArray(row.matched_rule_ids)
          && row.matched_rule_ids.length > 0
        )
      );


// ============================================================
// 7. Skip Reason
//
// 优先保留上游真实原因。
// ============================================================

const skipReason =
  row.skip_reason
  ?? row.scope_reason
  ?? row.analysis_scope_reason
  ?? 'OUT_OF_SCOPE_BY_BUSINESS_RULE';


// ============================================================
// 8. 输出 AI_Analysis 正式 34 字段
//
// 不额外增加 raw_id / source_staging_id，
// 保持 AI_Analysis V1 Schema 不变。
// ============================================================

return {
  json: {

    // --------------------------------------------------------
    // Group 1
    // Association / Version
    // --------------------------------------------------------

    analysis_id:
      analysisId,

    content_key:
      row.content_key,

    analysis_run_id:
      analysisRunId,

    analyzed_at:
      analyzedAt,

    rules_version:
      rulesVersion,

    // 没有调用 AI
    prompt_version:
      null,

    is_current:
      true,


    // --------------------------------------------------------
    // Group 2
    // Rule Engine
    // --------------------------------------------------------

    rule_hit:
      ruleHit,

    rule_tags:
      ruleTagsJson,

    // OUT_OF_SCOPE 没有进行正式风险分析，
    // 所以不要写 NONE。
    rule_risk_level:
      null,

    need_ai:
      false,


    // --------------------------------------------------------
    // Group 3
    // AI Result
    // --------------------------------------------------------

    ai_called:
      false,

    model_name:
      null,

    ai_category:
      null,

    ai_subcategory:
      null,

    ai_sentiment:
      null,

    ai_risk_level:
      null,

    ai_summary:
      null,

    confidence:
      null,


    // --------------------------------------------------------
    // Group 4
    // Final Decision
    //
    // 没进入正式分析，因此不存在 final 风险判断。
    // --------------------------------------------------------

    final_category:
      null,

    final_subcategory:
      null,

    final_sentiment:
      null,

    final_risk_level:
      null,

    final_summary:
      null,

    decision_source:
      null,


    // --------------------------------------------------------
    // Group 5
    // Usage / Performance
    //
    // AI 完全没调用，因此 Token 是真实的 0。
    // --------------------------------------------------------

    input_tokens:
      0,

    output_tokens:
      0,

    total_tokens:
      0,

    latency_ms:
      null,


    // --------------------------------------------------------
    // Group 6
    // Scope / Status
    // --------------------------------------------------------

    analysis_scope:
      'OUT_OF_SCOPE',

    analysis_status:
      'SKIPPED',

    skip_reason:
      skipReason,

    manual_review_required:
      false,

    error_message:
      null
  }
};

// ============================================================
// Analysis Records Validation v1.0
//
// 职责：
// 在 AI_Analysis 写入飞书之前，执行最终数据质量检查。
//
// 设计：
// - PASS：原样返回所有 records
// - FAIL：直接 throw Error，阻断后续写入
//
// 核心检查：
// 1. RAW/Source Mapper 与 Analysis 数量对账
// 2. 34 字段 Schema 一致性
// 3. analysis_id / content_key 唯一性
// 4. analysis_run_id 批次一致性
// 5. OUT_OF_SCOPE / RULE_ONLY / AI Path 语义一致性
// 6. Token / AI调用状态一致性
// 7. NONE / null / SKIPPED 语义一致性
// ============================================================


const items = $input.all();
const rows = items.map((item, index) => ({
  index: index + 1,
  json: item.json,
}));

const errors = [];
const warnings = [];


// ============================================================
// 1. AI_Analysis V1 正式 34 字段
// ============================================================

const EXPECTED_FIELDS = [
  'analysis_id',
  'content_key',
  'analysis_run_id',
  'analyzed_at',
  'rules_version',
  'prompt_version',
  'is_current',

  'rule_hit',
  'rule_tags',
  'rule_risk_level',
  'need_ai',

  'ai_called',
  'model_name',
  'ai_category',
  'ai_subcategory',
  'ai_sentiment',
  'ai_risk_level',
  'ai_summary',
  'confidence',

  'final_category',
  'final_subcategory',
  'final_sentiment',
  'final_risk_level',
  'final_summary',
  'decision_source',

  'input_tokens',
  'output_tokens',
  'total_tokens',
  'latency_ms',

  'analysis_scope',
  'analysis_status',
  'skip_reason',
  'manual_review_required',
  'error_message',
];

const EXPECTED_FIELD_SET =
  new Set(EXPECTED_FIELDS);


// ============================================================
// 2. 合法枚举
// ============================================================

const VALID_SCOPE =
  new Set([
    'IN_SCOPE',
    'OUT_OF_SCOPE',
  ]);

const VALID_STATUS =
  new Set([
    'SUCCESS',
    'SKIPPED',
    'ERROR',
  ]);

const VALID_RISK =
  new Set([
    'P0',
    'P1',
    'P2',
    'P3',
    'NONE',
  ]);

const VALID_SENTIMENT =
  new Set([
    'POSITIVE',
    'NEUTRAL',
    'NEGATIVE',
    'MIXED',
  ]);

const VALID_DECISION_SOURCE =
  new Set([
    'RULE',
    'AI',
    'RULE+AI',
    'MANUAL',
  ]);


// ============================================================
// 3. 工具函数
// ============================================================

function isNullish(value) {
  return (
    value === null ||
    value === undefined ||
    value === ''
  );
}


function addError(rowNo, code, message) {

  errors.push(
    `[Row ${rowNo}] ${code}: ${message}`
  );
}


function checkRisk(rowNo, fieldName, value) {

  if (
    !isNullish(value) &&
    !VALID_RISK.has(value)
  ) {

    addError(
      rowNo,
      'INVALID_RISK',
      `${fieldName}=${value}`
    );
  }
}


// ============================================================
// 4. 总数量 Reconciliation（对账）
//
// Source Mapper 是本轮标准化后的 content event 总数。
// Analysis 最终应该一条不少、一条不多。
// ============================================================

let sourceMapperCount = null;

try {

  sourceMapperCount =
    $('Source Mapper v1.0').all().length;

} catch (error) {

  warnings.push(
    `无法读取 Source Mapper v1.0 数量：${error.message}`
  );
}


if (
  sourceMapperCount !== null &&
  items.length !== sourceMapperCount
) {

  errors.push(
    `[RECONCILIATION] Source Mapper=${sourceMapperCount}，Analysis Records=${items.length}，数量不一致`
  );
}


// ============================================================
// 5. 唯一性容器
// ============================================================

const analysisIdMap =
  new Map();

const contentKeyMap =
  new Map();

const analysisRunIds =
  new Set();


// ============================================================
// 6. 路径计数
// ============================================================

let aiPathCount = 0;
let ruleOnlyCount = 0;
let outOfScopeCount = 0;

let successCount = 0;
let skippedCount = 0;
let errorCount = 0;


// ============================================================
// 7. 逐条校验
// ============================================================

for (const { index, json: row } of rows) {


  // ----------------------------------------------------------
  // A. Schema（字段结构）检查
  // ----------------------------------------------------------

  const actualFields =
    Object.keys(row);

  const actualFieldSet =
    new Set(actualFields);


  // 缺字段
  const missingFields =
    EXPECTED_FIELDS.filter(
      field => !actualFieldSet.has(field)
    );

  if (missingFields.length > 0) {

    addError(
      index,
      'MISSING_FIELDS',
      missingFields.join(', ')
    );
  }


  // 多字段
  const extraFields =
    actualFields.filter(
      field => !EXPECTED_FIELD_SET.has(field)
    );

  if (extraFields.length > 0) {

    addError(
      index,
      'EXTRA_FIELDS',
      extraFields.join(', ')
    );
  }


  // ----------------------------------------------------------
  // B. 基础必填追踪字段
  // ----------------------------------------------------------

  if (isNullish(row.analysis_id)) {

    addError(
      index,
      'ANALYSIS_ID_EMPTY',
      'analysis_id 不能为空'
    );

  } else {

    if (analysisIdMap.has(row.analysis_id)) {

      addError(
        index,
        'DUPLICATE_ANALYSIS_ID',
        `与 Row ${analysisIdMap.get(row.analysis_id)} 重复：${row.analysis_id}`
      );

    } else {

      analysisIdMap.set(
        row.analysis_id,
        index
      );
    }
  }


  if (isNullish(row.content_key)) {

    addError(
      index,
      'CONTENT_KEY_EMPTY',
      'content_key 不能为空'
    );

  } else {

    if (contentKeyMap.has(row.content_key)) {

      addError(
        index,
        'DUPLICATE_CONTENT_KEY',
        `本次分析批次中与 Row ${contentKeyMap.get(row.content_key)} 重复`
      );

    } else {

      contentKeyMap.set(
        row.content_key,
        index
      );
    }
  }


  if (isNullish(row.analysis_run_id)) {

    addError(
      index,
      'RUN_ID_EMPTY',
      'analysis_run_id 不能为空'
    );

  } else {

    analysisRunIds.add(
      row.analysis_run_id
    );
  }


  if (isNullish(row.analyzed_at)) {

    addError(
      index,
      'ANALYZED_AT_EMPTY',
      'analyzed_at 不能为空'
    );
  }


  if (row.is_current !== true) {

    addError(
      index,
      'IS_CURRENT_INVALID',
      '新生成的分析记录 is_current 应为 true'
    );
  }


  // ----------------------------------------------------------
  // C. Enum（枚举）检查
  // ----------------------------------------------------------

  if (!VALID_SCOPE.has(row.analysis_scope)) {

    addError(
      index,
      'INVALID_SCOPE',
      `analysis_scope=${row.analysis_scope}`
    );
  }


  if (!VALID_STATUS.has(row.analysis_status)) {

    addError(
      index,
      'INVALID_STATUS',
      `analysis_status=${row.analysis_status}`
    );
  }


  checkRisk(
    index,
    'rule_risk_level',
    row.rule_risk_level
  );

  checkRisk(
    index,
    'ai_risk_level',
    row.ai_risk_level
  );

  checkRisk(
    index,
    'final_risk_level',
    row.final_risk_level
  );


  if (
    !isNullish(row.ai_sentiment) &&
    !VALID_SENTIMENT.has(row.ai_sentiment)
  ) {

    addError(
      index,
      'INVALID_AI_SENTIMENT',
      `ai_sentiment=${row.ai_sentiment}`
    );
  }


  if (
    !isNullish(row.final_sentiment) &&
    !VALID_SENTIMENT.has(row.final_sentiment)
  ) {

    addError(
      index,
      'INVALID_FINAL_SENTIMENT',
      `final_sentiment=${row.final_sentiment}`
    );
  }


  if (
    !isNullish(row.decision_source) &&
    !VALID_DECISION_SOURCE.has(row.decision_source)
  ) {

    addError(
      index,
      'INVALID_DECISION_SOURCE',
      `decision_source=${row.decision_source}`
    );
  }


  // ----------------------------------------------------------
  // D. rule_tags 必须是 JSON Array String
  // ----------------------------------------------------------

  try {

    const parsedTags =
      JSON.parse(row.rule_tags);

    if (!Array.isArray(parsedTags)) {

      addError(
        index,
        'RULE_TAGS_NOT_ARRAY',
        'rule_tags 解析后不是数组'
      );
    }

  } catch {

    addError(
      index,
      'RULE_TAGS_INVALID_JSON',
      `rule_tags=${row.rule_tags}`
    );
  }


  // ----------------------------------------------------------
  // E. Status 计数
  // ----------------------------------------------------------

  if (row.analysis_status === 'SUCCESS') {
    successCount++;
  }

  if (row.analysis_status === 'SKIPPED') {
    skippedCount++;
  }

  if (row.analysis_status === 'ERROR') {
    errorCount++;
  }


  // ==========================================================
  // F. OUT_OF_SCOPE 路径
  // ==========================================================

  if (row.analysis_scope === 'OUT_OF_SCOPE') {

    outOfScopeCount++;


    if (row.analysis_status !== 'SKIPPED') {

      addError(
        index,
        'OUT_SCOPE_STATUS',
        'OUT_OF_SCOPE 必须对应 SKIPPED'
      );
    }


    if (row.need_ai !== false) {

      addError(
        index,
        'OUT_SCOPE_NEED_AI',
        'OUT_OF_SCOPE 的 need_ai 必须为 false'
      );
    }


    if (row.ai_called !== false) {

      addError(
        index,
        'OUT_SCOPE_AI_CALLED',
        'OUT_OF_SCOPE 不允许调用 AI'
      );
    }


    if (!isNullish(row.final_risk_level)) {

      addError(
        index,
        'OUT_SCOPE_FINAL_RISK',
        'OUT_OF_SCOPE 的 final_risk_level 必须为空'
      );
    }


    if (!isNullish(row.decision_source)) {

      addError(
        index,
        'OUT_SCOPE_DECISION_SOURCE',
        'OUT_OF_SCOPE 不应有 decision_source'
      );
    }


    if (isNullish(row.skip_reason)) {

      addError(
        index,
        'OUT_SCOPE_SKIP_REASON',
        'OUT_OF_SCOPE 必须有 skip_reason'
      );
    }


    if (
      row.input_tokens !== 0 ||
      row.output_tokens !== 0 ||
      row.total_tokens !== 0
    ) {

      addError(
        index,
        'OUT_SCOPE_TOKEN',
        'OUT_OF_SCOPE 的 Token 必须全部为 0'
      );
    }


    if (!isNullish(row.latency_ms)) {

      addError(
        index,
        'OUT_SCOPE_LATENCY',
        'OUT_OF_SCOPE 的 latency_ms 应为空'
      );
    }


    continue;
  }


  // ==========================================================
  // G. IN_SCOPE 基础规则
  // ==========================================================

  if (row.analysis_scope === 'IN_SCOPE') {

    if (row.analysis_status === 'SKIPPED') {

      addError(
        index,
        'IN_SCOPE_SKIPPED',
        'IN_SCOPE 不应该出现 SKIPPED'
      );
    }


    // ========================================================
    // G1. AI_REQUIRED Path
    // ========================================================

    if (row.need_ai === true) {

      aiPathCount++;


      if (row.ai_called !== true) {

        addError(
          index,
          'AI_PATH_NOT_CALLED',
          'need_ai=true 时 ai_called 应为 true'
        );
      }


      if (isNullish(row.prompt_version)) {

        addError(
          index,
          'AI_PATH_PROMPT_VERSION',
          'AI调用记录必须有 prompt_version'
        );
      }


      if (isNullish(row.model_name)) {

        addError(
          index,
          'AI_PATH_MODEL_NAME',
          'AI调用记录必须有 model_name'
        );
      }


      // AI 成功时必须有完整语义结果
      if (row.analysis_status === 'SUCCESS') {

        if (isNullish(row.ai_category)) {

          addError(
            index,
            'AI_CATEGORY_EMPTY',
            'SUCCESS 的 AI记录必须有 ai_category'
          );
        }


        if (isNullish(row.ai_sentiment)) {

          addError(
            index,
            'AI_SENTIMENT_EMPTY',
            'SUCCESS 的 AI记录必须有 ai_sentiment'
          );
        }


        if (isNullish(row.ai_risk_level)) {

          addError(
            index,
            'AI_RISK_EMPTY',
            'SUCCESS 的 AI记录必须有 ai_risk_level'
          );
        }


        if (isNullish(row.final_risk_level)) {

          addError(
            index,
            'FINAL_RISK_EMPTY',
            'SUCCESS 的 AI记录必须有 final_risk_level'
          );
        }


        if (
          typeof row.total_tokens !== 'number' ||
          row.total_tokens <= 0
        ) {

          addError(
            index,
            'AI_TOKEN_INVALID',
            `AI成功调用 total_tokens 应 > 0，实际=${row.total_tokens}`
          );
        }


        if (
          typeof row.latency_ms !== 'number' ||
          row.latency_ms <= 0
        ) {

          addError(
            index,
            'AI_LATENCY_INVALID',
            `AI成功调用 latency_ms 应 > 0，实际=${row.latency_ms}`
          );
        }
      }


      // AI失败必须要求人工复核
      if (
        row.analysis_status === 'ERROR' &&
        row.manual_review_required !== true
      ) {

        addError(
          index,
          'AI_ERROR_MANUAL_REVIEW',
          'AI分析 ERROR 时 manual_review_required 必须为 true'
        );
      }


      continue;
    }


    // ========================================================
    // G2. RULE_ONLY Path
    // ========================================================

    if (row.need_ai === false) {

      ruleOnlyCount++;


      if (row.ai_called !== false) {

        addError(
          index,
          'RULE_ONLY_AI_CALLED',
          'RULE_ONLY 不允许调用 AI'
        );
      }


      if (!isNullish(row.model_name)) {

        addError(
          index,
          'RULE_ONLY_MODEL',
          'RULE_ONLY 的 model_name 应为空'
        );
      }


      if (!isNullish(row.prompt_version)) {

        addError(
          index,
          'RULE_ONLY_PROMPT',
          'RULE_ONLY 的 prompt_version 应为空'
        );
      }


      if (
        row.input_tokens !== 0 ||
        row.output_tokens !== 0 ||
        row.total_tokens !== 0
      ) {

        addError(
          index,
          'RULE_ONLY_TOKEN',
          'RULE_ONLY 的 Token 必须全部为 0'
        );
      }


      if (!isNullish(row.latency_ms)) {

        addError(
          index,
          'RULE_ONLY_LATENCY',
          'RULE_ONLY 的 latency_ms 应为空'
        );
      }


      if (
        row.analysis_status === 'SUCCESS' &&
        isNullish(row.final_risk_level)
      ) {

        addError(
          index,
          'RULE_ONLY_FINAL_RISK',
          'RULE_ONLY SUCCESS 必须有 final_risk_level'
        );
      }


      if (
        row.analysis_status === 'SUCCESS' &&
        row.decision_source !== 'RULE'
      ) {

        addError(
          index,
          'RULE_ONLY_SOURCE',
          `RULE_ONLY SUCCESS 的 decision_source 应为 RULE，实际=${row.decision_source}`
        );
      }


      continue;
    }


    // need_ai 既不是 true 也不是 false
    addError(
      index,
      'NEED_AI_INVALID',
      `IN_SCOPE 的 need_ai 必须是 boolean，实际=${row.need_ai}`
    );
  }
}


// ============================================================
// 8. analysis_run_id 批次一致性
//
// 同一次完整 workflow execution 产生的 57 条
// 应共享同一个 analysis_run_id。
// ============================================================

if (analysisRunIds.size !== 1) {

  errors.push(
    `[RUN_ID_MISMATCH] 本批数据出现 ${analysisRunIds.size} 个 analysis_run_id：${Array.from(analysisRunIds).join(', ')}`
  );
}


// ============================================================
// 9. 三路径总数再次对账
// ============================================================

const classifiedCount =
  aiPathCount +
  ruleOnlyCount +
  outOfScopeCount;

if (classifiedCount !== items.length) {

  errors.push(
    `[PATH_COUNT] AI=${aiPathCount} + RULE_ONLY=${ruleOnlyCount} + OUT_OF_SCOPE=${outOfScopeCount} = ${classifiedCount}，但总记录=${items.length}`
  );
}


// ============================================================
// 10. 汇总信息
// ============================================================

const summary = {
  total_records:
    items.length,

  source_mapper_records:
    sourceMapperCount,

  ai_path_count:
    aiPathCount,

  rule_only_count:
    ruleOnlyCount,

  out_of_scope_count:
    outOfScopeCount,

  success_count:
    successCount,

  skipped_count:
    skippedCount,

  error_count:
    errorCount,

  unique_analysis_ids:
    analysisIdMap.size,

  unique_content_keys:
    contentKeyMap.size,

  analysis_run_ids:
    Array.from(analysisRunIds),

  warning_count:
    warnings.length,

  error_count_validation:
    errors.length,
};


// ============================================================
// 11. FAIL FAST（快速失败）
//
// 正式运行模式：
// 只要写入前校验发现错误，立即终止流程，
// 禁止错误数据继续写入飞书。
// ============================================================

if (errors.length > 0) {
  throw new Error(
    'Analysis Records Validation v1.0 FAILED\n\n' +
    errors.join('\n')
  );
}


// ============================================================
// 12. PASS
//
// 不增加任何字段。
// 原样返回 57 条，供下一步写飞书。
// ============================================================

console.log(
  'Analysis Records Validation v1.0 PASS',
  summary
);

return items;

const items = $input.all();

const CURRENT_PROMPT_VERSION = 'review-v1.0';
const CURRENT_MODEL_NAME = 'DeepSeek V4.1 Flash';

function clean(v) {
  if (v === undefined || v === null) return null;
  return String(v).trim();
}

const output = items.map((item) => {
  const row = item.json;

  const contentKey = clean(row.content_key);
  const analysisScope = clean(row.analysis_scope);
  const currentRulesVersion = clean(row.rules_version);

  const existingAnalysisId = clean(row.existing_analysis_id);
  const existingStatus = clean(row.existing_analysis_status);
  const existingRulesVersion = clean(row.existing_rules_version);
  const existingPromptVersion = clean(row.existing_prompt_version);
  const existingModelName = clean(row.existing_model_name);
  const existingScope = clean(row.existing_analysis_scope);

  const currentNeedAi = row.need_ai === true;
  const existingNeedAi = row.existing_need_ai === true;

  let action = null;
  let reason = null;

  // 基础保护
  if (!contentKey) {
    action = 'REVIEW_REQUIRED';
    reason = 'MISSING_CONTENT_KEY';
  }

  // 从未分析过
  else if (!existingAnalysisId) {
    action = 'PROCESS_REQUIRED';
    reason = 'NO_CURRENT_ANALYSIS';
  }

  // 规则版本发生变化
  else if (existingRulesVersion !== currentRulesVersion) {
    action = 'PROCESS_REQUIRED';
    reason = 'RULES_VERSION_CHANGED';
  }

  // OUT_OF_SCOPE：只由规则决定，不关心 Prompt / Model
  else if (analysisScope === 'OUT_OF_SCOPE') {
    if (
      existingScope === 'OUT_OF_SCOPE' &&
      existingStatus === 'SKIPPED'
    ) {
      action = 'SKIP_UP_TO_DATE';
      reason = 'EXISTING_OUT_OF_SCOPE_IS_CURRENT';
    } else {
      action = 'PROCESS_REQUIRED';
      reason = 'SCOPE_OR_STATUS_CHANGED';
    }
  }

  // IN_SCOPE + RULE_ONLY
  else if (
    analysisScope === 'IN_SCOPE' &&
    currentNeedAi === false
  ) {
    if (
      existingScope === 'IN_SCOPE' &&
      existingStatus === 'SUCCESS' &&
      existingNeedAi === false
    ) {
      action = 'SKIP_UP_TO_DATE';
      reason = 'EXISTING_RULE_ONLY_IS_CURRENT';
    } else {
      action = 'PROCESS_REQUIRED';
      reason = 'ANALYSIS_PATH_CHANGED';
    }
  }

  // IN_SCOPE + AI_REQUIRED
  else if (
    analysisScope === 'IN_SCOPE' &&
    currentNeedAi === true
  ) {
    if (
      existingScope !== 'IN_SCOPE' ||
      existingStatus !== 'SUCCESS' ||
      existingNeedAi !== true
    ) {
      action = 'PROCESS_REQUIRED';
      reason = 'ANALYSIS_PATH_OR_STATUS_CHANGED';
    } else if (
      existingPromptVersion !== CURRENT_PROMPT_VERSION
    ) {
      action = 'PROCESS_REQUIRED';
      reason = 'PROMPT_VERSION_CHANGED';
    } else if (
      existingModelName !== CURRENT_MODEL_NAME
    ) {
      action = 'PROCESS_REQUIRED';
      reason = 'MODEL_CHANGED';
    } else {
      action = 'SKIP_UP_TO_DATE';
      reason = 'EXISTING_AI_ANALYSIS_IS_CURRENT';
    }
  }

  // 理论上不应进入
  else {
    action = 'REVIEW_REQUIRED';
    reason = 'UNEXPECTED_PRE_ANALYSIS_STATE';
  }

  return {
    json: {
      ...row,

      pre_analysis_action: action,
      pre_analysis_reason: reason,

      current_rules_version: currentRulesVersion,
      current_prompt_version: CURRENT_PROMPT_VERSION,
      current_model_name: CURRENT_MODEL_NAME
    }
  };
});

return output;

// ============================================================
// Prepare Skip Raw Processed Update v1.0
//
// 场景：
// PostgreSQL raw_reviews 仍然是 NEW，
// 但飞书 AI_Analysis 已经存在最新有效分析。
//
// 所以：
// - 不重新调用 AI
// - 不重新写 AI_Analysis
// - 只补做 raw_reviews → PROCESSED
// ============================================================

const row = $json;

if (row.pre_analysis_action !== 'SKIP_UP_TO_DATE') {
  throw new Error(
    `Prepare Skip Raw Processed Update v1.0: 收到非 SKIP_UP_TO_DATE 数据，content_key=${row.content_key}`
  );
}

if (!row.content_key) {
  throw new Error(
    'Prepare Skip Raw Processed Update v1.0: 缺少 content_key'
  );
}

return {
  json: {
    content_key: row.content_key,

    // 已经存在的分析记录，仅用于追踪
    analysis_id:
      row.existing_analysis_id ?? null,

    feishu_analysis_record_id:
      row.existing_analysis_record_id ?? null,

    // 当前这一次工作流负责把 RAW 补标完成
    analysis_run_id:
      `N8N_${$execution.id}`
  }
};

// ============================================================
// Prepare Analysis Route Error v1.0
//
// 职责：
// Route Analysis Path 无法归入任何正常业务分支时，
// 生成明确错误信息，供 PostgreSQL raw_reviews 标记 ERROR。
// ============================================================

const row = $json;

if (
  row.raw_id === undefined ||
  row.raw_id === null ||
  row.raw_id === ''
) {
  throw new Error(
    `Prepare Analysis Route Error v1.0: 缺少 raw_id，content_key=${row.content_key}`
  );
}

if (!row.content_key) {
  throw new Error(
    `Prepare Analysis Route Error v1.0: 缺少 content_key，raw_id=${row.raw_id}`
  );
}

const pipelineRunId =
  `N8N_${$execution.id}`;

const errorMessage =
  [
    'UNMATCHED_ANALYSIS_PATH',
    `analysis_scope=${row.analysis_scope ?? 'null'}`,
    `need_ai=${row.need_ai ?? 'null'}`,
    `rule_decision=${row.rule_decision ?? 'null'}`,
    `rule_risk_level=${row.rule_risk_level ?? 'null'}`
  ].join(' | ');

return {
  json: {
    raw_id: row.raw_id,
    content_key: row.content_key,
    pipeline_run_id: pipelineRunId,

    // 继续沿用现有 last_error_stage 枚举，
    // 这里属于规则/路由判断阶段。
    error_stage: 'RULE',

    error_message: errorMessage
  }
};

// ============================================================
// Prepare Pre-Analysis Route Error v1.0
//
// 职责：
// Pre-Analysis Gate 返回非正常动作时，
// 整理错误信息，供 PostgreSQL raw_reviews 标记 ERROR。
// ============================================================

const row = $json;


// ============================================================
// 1. 基础校验
// ============================================================

if (
  row.raw_id === undefined ||
  row.raw_id === null ||
  row.raw_id === ''
) {
  throw new Error(
    `Prepare Pre-Analysis Route Error v1.0: 缺少 raw_id，content_key=${row.content_key}`
  );
}

if (!row.content_key) {
  throw new Error(
    `Prepare Pre-Analysis Route Error v1.0: 缺少 content_key，raw_id=${row.raw_id}`
  );
}


// ============================================================
// 2. 防御性检查
//
// 正常动作不应该进入这个分支。
// ============================================================

if (
  row.pre_analysis_action === 'PROCESS_REQUIRED'
  || row.pre_analysis_action === 'SKIP_UP_TO_DATE'
) {
  throw new Error(
    `Prepare Pre-Analysis Route Error v1.0: 正常动作误入异常分支，action=${row.pre_analysis_action}, content_key=${row.content_key}`
  );
}


// ============================================================
// 3. 错误上下文
// ============================================================

const pipelineRunId =
  `N8N_${$execution.id}`;

const errorMessage =
  [
    'PRE_ANALYSIS_ROUTE_ERROR',
    `action=${row.pre_analysis_action ?? 'null'}`,
    `reason=${row.pre_analysis_reason ?? 'null'}`,
    `existing_analysis_id=${row.existing_analysis_id ?? 'null'}`,
    `existing_analysis_status=${row.existing_analysis_status ?? 'null'}`,
    `current_rules_version=${row.current_rules_version ?? row.rules_version ?? 'null'}`,
    `current_prompt_version=${row.current_prompt_version ?? 'null'}`,
    `current_model_name=${row.current_model_name ?? 'null'}`
  ].join(' | ');


// ============================================================
// 4. 输出
// ============================================================

return {
  json: {
    raw_id: row.raw_id,
    content_key: row.content_key,
    pipeline_run_id: pipelineRunId,

    // 这里属于流程判断 / 幂等路由阶段，
    // 不是 AI 模型调用错误，也不是采集错误。
    error_stage: 'RULE',

    error_message: errorMessage
  }
};

// ============================================================
// Prepare PostgreSQL Analysis Record v1.0
//
// 职责：
// 将 AI_Analysis V1 标准记录转换成
// voc.write_analysis_result(p_record jsonb)
// 需要的 PostgreSQL JSON 结构。
//
// 本节点：
// - 不写数据库
// - 不改变业务判断
// - 只做类型转换与严格校验
// ============================================================

const row = $json;


// ============================================================
// 1. 基础必填字段
// ============================================================

const requiredFields = [
  'content_key',
  'rules_version',
  'analysis_scope',
  'analysis_status',
  'analyzed_at',
  'rule_hit',
  'need_ai',
  'ai_called',
  'manual_review_required'
];

for (const field of requiredFields) {
  if (
    row[field] === undefined ||
    row[field] === null
  ) {
    throw new Error(
      `Prepare PostgreSQL Analysis Record v1.0: 缺少必填字段 ${field}, content_key=${row.content_key ?? 'UNKNOWN'}`
    );
  }
}


// ============================================================
// 2. rule_tags
//
// 当前 Builder 输出仍可能是 JSON 字符串：
// '["A","B"]'
//
// PostgreSQL Writer 要真正 JSON array。
// ============================================================

let ruleTags = null;

if (row.rule_tags === null || row.rule_tags === undefined || row.rule_tags === '') {

  ruleTags = null;

} else if (Array.isArray(row.rule_tags)) {

  ruleTags = row.rule_tags;

} else if (typeof row.rule_tags === 'string') {

  let parsed;

  try {
    parsed = JSON.parse(row.rule_tags);
  } catch {
    throw new Error(
      `Prepare PostgreSQL Analysis Record v1.0: rule_tags 不是合法 JSON，content_key=${row.content_key}`
    );
  }

  if (!Array.isArray(parsed)) {
    throw new Error(
      `Prepare PostgreSQL Analysis Record v1.0: rule_tags JSON 不是 array，content_key=${row.content_key}`
    );
  }

  ruleTags = parsed;

} else {

  throw new Error(
    `Prepare PostgreSQL Analysis Record v1.0: rule_tags 类型非法，content_key=${row.content_key}`
  );
}


// ============================================================
// 3. Token 类型保护
//
// NULL 保持 NULL。
// 0 保持 0。
// 禁止 undefined 被默认为 0。
// ============================================================

function nullableNumber(value, fieldName) {

  if (value === undefined || value === null || value === '') {
    return null;
  }

  const n = Number(value);

  if (!Number.isFinite(n)) {
    throw new Error(
      `Prepare PostgreSQL Analysis Record v1.0: ${fieldName} 不是合法数字，content_key=${row.content_key}`
    );
  }

  return n;
}

const inputTokens =
  nullableNumber(row.input_tokens, 'input_tokens');

const outputTokens =
  nullableNumber(row.output_tokens, 'output_tokens');

const totalTokens =
  nullableNumber(row.total_tokens, 'total_tokens');

const latencyMs =
  nullableNumber(row.latency_ms, 'latency_ms');

const confidence =
  nullableNumber(row.confidence, 'confidence');


// ============================================================
// 4. Scope / Status 不做业务修正
// ============================================================

if (
  row.analysis_scope === 'OUT_OF_SCOPE' &&
  row.analysis_status !== 'SKIPPED'
) {
  throw new Error(
    `Prepare PostgreSQL Analysis Record v1.0: OUT_OF_SCOPE 必须为 SKIPPED，content_key=${row.content_key}`
  );
}

if (
  row.analysis_scope === 'IN_SCOPE' &&
  row.analysis_status === 'SUCCESS' &&
  (row.final_risk_level === null || row.final_risk_level === undefined || row.final_risk_level === '')
) {
  throw new Error(
    `Prepare PostgreSQL Analysis Record v1.0: IN_SCOPE + SUCCESS 缺少 final_risk_level，content_key=${row.content_key}`
  );
}


// ============================================================
// 5. 输出 Writer JSON
//
// 不传：
// analysis_id
// is_current
// created_at
// updated_at
//
// 这些由 PostgreSQL 管理。
// ============================================================

return {
  json: {
    content_key:
      row.content_key,

    analysis_run_id:
      row.analysis_run_id ?? null,

    analyzed_at:
      row.analyzed_at,

    rules_version:
      row.rules_version,

    prompt_version:
      row.prompt_version ?? null,

    model_name:
      row.model_name ?? null,

    rule_hit:
      Boolean(row.rule_hit),

    rule_tags:
      ruleTags,

    rule_risk_level:
      row.rule_risk_level ?? null,

    need_ai:
      Boolean(row.need_ai),

    ai_called:
      Boolean(row.ai_called),

    ai_category:
      row.ai_category ?? null,

    ai_subcategory:
      row.ai_subcategory ?? null,

    ai_sentiment:
      row.ai_sentiment ?? null,

    ai_risk_level:
      row.ai_risk_level ?? null,

    ai_summary:
      row.ai_summary ?? null,

    confidence:
      confidence,

    final_category:
      row.final_category ?? null,

    final_subcategory:
      row.final_subcategory ?? null,

    final_sentiment:
      row.final_sentiment ?? null,

    final_risk_level:
      row.final_risk_level ?? null,

    final_summary:
      row.final_summary ?? null,

    decision_source:
      row.decision_source ?? null,

    input_tokens:
      inputTokens,

    output_tokens:
      outputTokens,

    total_tokens:
      totalTokens,

    latency_ms:
      latencyMs,

    analysis_scope:
      row.analysis_scope,

    analysis_status:
      row.analysis_status,

    skip_reason:
      row.skip_reason ?? null,

    manual_review_required:
      Boolean(row.manual_review_required),

    error_message:
      row.error_message ?? null
  }
};
